L["%s: %s is up."] = "%s: hai già %s."
L["%s: Automatic, and your group role is not tank, so it is not offered."] = "%s: Automatico, e il tuo ruolo nel gruppo non è difensore, quindi non viene proposto nulla."
L["%s: %s was pressed or skipped a moment ago."] = "%s: hai premuto o saltato %s poco fa."
L["%s: the game says %s cannot be cast right now."] = "%s: secondo il gioco, ora non puoi lanciare %s."
L["%s: Automatic has nothing it would pick."] = "%s: Automatico non ha niente da scegliere."
L["%s: the game will not say whether it is up, so it is not offered."] = "%s: il gioco non dice se ce l'hai, quindi non viene proposto nulla."
L["your own buffs: held back -- you are in a city or an inn, and %s is off."] = "i tuoi benefici personali: trattenuti -- sei in città o in una locanda, e l'opzione %s è disattivata."
L["Also in cities and inns"] = "Anche in città e locande"
L["your own %s comes first -- the buffs below wait until it has been cast."] = "prima viene %s su di te -- i benefici qui sotto aspettano il suo lancio."
L["this class has no buffs to cast on other players."] = "questa classe non ha benefici da lanciare su altri giocatori."
L["|cffff8080not during a fight|r -- the prompt cannot be put on screen while one is on. Try again when it ends."] = "|cffff8080non durante il combattimento|r -- il riquadro non può comparire sullo schermo mentre è in corso. Riprova quando finisce."
L["|cffffd100Manners|r is installed, but this class has no buffs to cast on other players."] = "|cffffd100Manners|r è installato, ma questa classe non ha benefici da lanciare su altri giocatori."
L["It is still worth keeping for an alt that does -- it will say hello again there."] = "Vale comunque la pena tenerlo per un alt che ne ha -- lì ti saluterà di nuovo."
L["|cffffd100Manners|r is installed, but nothing will be offered to anybody: %s."] = "|cffffd100Manners|r è installato, ma non proporrà niente a nessuno: %s."
L["|cffffd100/manners welcome|r brings the rest of this back once that changes."] = "|cffffd100/manners welcome|r ti mostra il resto di questo messaggio quando le cose cambiano."
L["|cffffd100Manners|r puts your own buffs on a small prompt when none of them is up -- your class has none for other players. Clicking the prompt casts it on you."] = "|cffffd100Manners|r mostra in un piccolo riquadro i tuoi benefici personali quando nessuno è attivo -- la tua classe non ne ha per gli altri giocatori. Fai clic sul riquadro e l'incantesimo parte su di te."
L["|cffffd100Manners|r puts your own buffs on a small prompt when none of them is up; nothing is offered to anybody else: %s. Clicking the prompt casts it on you."] = "|cffffd100Manners|r mostra in un piccolo riquadro i tuoi benefici personali quando nessuno è attivo; agli altri non viene proposto niente: %s. Fai clic sul riquadro e l'incantesimo parte su di te."
L["|cffffd100Manners|r puts anybody in your group who is missing your |cffffd100%s|r -- or who has just buffed you -- on a small prompt. Clicking the prompt casts it."] = "|cffffd100Manners|r mostra in un piccolo riquadro chiunque nel tuo gruppo sia senza |cffffd100%s|r -- o ti abbia appena dato un beneficio. Fai clic sul riquadro e parte l'incantesimo."
L["|cffffd100Manners|r puts anybody in your group who is missing your |cffffd100buff|r -- or who has just buffed you -- on a small prompt. Clicking the prompt casts it."] = "|cffffd100Manners|r mostra in un piccolo riquadro chiunque nel tuo gruppo sia senza il tuo |cffffd100beneficio|r -- o ti abbia appena dato un beneficio. Fai clic sul riquadro e parte l'incantesimo."
L["|cffffd100Manners|r puts anybody who buffs you -- and any stranger nearby who is missing one of yours -- on a small prompt. Clicking the prompt buffs them."] = "|cffffd100Manners|r mostra in un piccolo riquadro chiunque ti dia un beneficio -- e ogni sconosciuto vicino a cui manca uno dei tuoi. Fai clic sul riquadro per dargli un beneficio."
L["The one thing that is not automatic: |cffffd100/manners macro|r or |cffffd100Make a macro|r in the options makes a macro for your bars, or bind a key under Options > Keybindings > Manners."] = "L'unica cosa che non è automatica: |cffffd100/manners macro|r o |cffffd100Crea una macro|r nelle opzioni crea una macro da mettere sulle tue barre, oppure assegna un tasto in Opzioni > Assegnazione tasti > Manners."
L["|cffff8080It is switched off on this profile|r, so no prompt will appear -- |cffffd100/manners on|r when you want it."] = "|cffff8080È disattivato in questo profilo|r, quindi non comparirà nessun riquadro -- |cffffd100/manners on|r quando lo vuoi."
L["The prompt is on screen now, with somebody real on it already. |cffffd100/manners welcome|r brings this back."] = "Il riquadro è già sullo schermo, con un giocatore vero. |cffffd100/manners welcome|r ti mostra di nuovo questo messaggio."
L["That is the prompt, with a pretend name on it. |cffffd100/manners welcome|r brings this back."] = "Questo è il riquadro, con un nome finto. |cffffd100/manners welcome|r ti mostra di nuovo questo messaggio."
L["does not exist (or its existence is withheld)"] = "non esiste (o la sua esistenza è nascosta)"
L["withheld: %s"] = "dati nascosti: %s"
L["this buff is not readable here"] = "questo beneficio qui non è leggibile"
L["%s has no unit token right now, so {unit} cannot be filled"] = "%s ora non ha un token di unità, quindi {unit} non si può compilare"
L["1 minute"] = "1 minuto"
L["%d minutes"] = "%d minuti"
L["snoozed for %s, until %s -- though Manners is switched off, so no prompt appears either way."] = "in pausa per %s, fino alle %s -- però Manners è disattivato, quindi il riquadro non compare comunque."
L["snoozed for %s, until %s. In a fight the prompt stays as the fight found it, and follows the snooze once this one ends. |cffffd100/manners snooze off|r ends it early."] = "in pausa per %s, fino alle %s. In combattimento il riquadro resta com'era all'inizio del combattimento, e segue la pausa quando questo finisce. |cffffd100/manners snooze off|r la termina prima."
L["snoozed for %s, until %s. The prompt is unlocked, so it stays up to be dragged and casts nothing; once you lock it, it stays away until the snooze ends. |cffffd100/manners snooze off|r ends it early."] = "in pausa per %s, fino alle %s. Il riquadro è sbloccato, quindi resta visibile per essere trascinato e non lancia niente; quando lo blocchi, resta nascosto finché la pausa non finisce. |cffffd100/manners snooze off|r la termina prima."
L["snoozed for %s -- no prompt until %s. |cffffd100/manners snooze off|r ends it early."] = "in pausa per %s -- nessun riquadro fino alle %s. |cffffd100/manners snooze off|r la termina prima."
L["the snooze is over, but Manners is switched off -- |cffffd100/manners on|r to see the prompt again."] = "la pausa è finita, ma Manners è disattivato -- |cffffd100/manners on|r per rivedere il riquadro."
L["the snooze is over -- the prompt can appear again once this fight ends."] = "la pausa è finita -- il riquadro può ricomparire quando finisce questo combattimento."
L["the snooze is over -- the prompt can appear again."] = "la pausa è finita -- il riquadro può ricomparire."
L["not snoozed -- the prompt is free to appear."] = "nessuna pausa -- il riquadro può comparire liberamente."
L["there is nothing to import -- paste a settings string that starts with MNR1:."] = "non c'è niente da importare -- incolla una stringa delle impostazioni che inizia con MNR1:."
L["that is not a Manners settings string -- one starts with MNR1:."] = "questa non è una stringa delle impostazioni di Manners -- quelle giuste iniziano con MNR1:."
L["that is far longer than any Manners settings string, so it was not read."] = "questo testo è troppo lungo per essere una stringa delle impostazioni di Manners, quindi non è stato letto."
L["that string was made by a newer version of Manners -- update the addon to read it."] = "quella stringa è stata creata da una versione più recente di Manners -- aggiorna l'add-on per leggerla."
L["that string is incomplete or has been changed -- copy it again in one piece, and paste a long one into the box under Share as text on the Profiles tab of the options."] = "quella stringa è incompleta o è stata modificata -- copiala di nuovo tutta intera, e incolla quelle lunghe nella casella sotto Condividi come testo, nella scheda Profili delle opzioni."
L["that string is damaged -- part of it is not a setting Manners can read. Copy it again in one piece."] = "quella stringa è danneggiata -- una sua parte non è un'impostazione che Manners sa leggere. Copiala di nuovo tutta intera."
L["that string gives %s a value it cannot have, so nothing was changed."] = "quella stringa dà a %s un valore che non può avere, quindi non è stato cambiato niente."
L["settings imported -- every one of them is the default."] = "impostazioni importate -- sono tutte quelle predefinite."
L["settings imported -- 1 differs from the defaults."] = "impostazioni importate -- 1 è diversa da quelle predefinite."
L["settings imported -- %d differ from the defaults."] = "impostazioni importate -- %d sono diverse da quelle predefinite."
L["1 setting from a newer version of Manners was left out."] = "1 impostazione di una versione più recente di Manners è stata tralasciata."
L["%d settings from a newer version of Manners were left out."] = "%d impostazioni di una versione più recente di Manners sono state tralasciate."
L["The string had speaking a line when you buff switched on. That is left off, because it talks to other players: switch it on under What I say if you want it."] = "Nella stringa era attiva l'opzione per dire una frase quando dai un beneficio. Resta disattivata, perché manda messaggi agli altri giocatori: attivala nella scheda Cosa dico, se la vuoi."
L["What you say when you buff, and where, is kept as you had it, because you have speaking switched on."] = "Cosa dici quando dai un beneficio, e dove, resta com'era, perché tu hai già attivato le frasi."
L["The prompt's look changes when this fight ends."] = "L'aspetto del riquadro cambia quando finisce questo combattimento."
L["|cffffd100/manners import undo|r puts your old settings back."] = "|cffffd100/manners import undo|r ripristina le impostazioni precedenti."
L["nothing to undo -- no settings have been imported on this profile this session."] = "niente da annullare -- in questa sessione non sono state importate impostazioni in questo profilo."
L["nothing to undo on this profile -- the last import was made on profile %s. Switch back to it to undo it."] = "niente da annullare in questo profilo -- l'ultima importazione è stata fatta nel profilo %s. Torna a quel profilo per annullarla."
L["nothing to undo on this profile -- the last import was made on another one. Switch back to it to undo it."] = "niente da annullare in questo profilo -- l'ultima importazione è stata fatta in un altro profilo. Torna a quel profilo per annullarla."
L["your settings from before the import could not be read back, so they were not restored."] = "non è stato possibile rileggere le impostazioni di prima dell'importazione, quindi non sono state ripristinate."
L["your settings from before the import are back. The prompt's look changes when this fight ends."] = "sono tornate le impostazioni di prima dell'importazione. L'aspetto del riquadro cambia quando finisce questo combattimento."
L["your settings from before the import are back."] = "sono tornate le impostazioni di prima dell'importazione."
L["Everyday"] = "Uso quotidiano"
L["Setting it up"] = "Configurazione"
L["Sharing settings"] = "Condividere le impostazioni"
L["When something is wrong"] = "Quando qualcosa non va"
L["open the options window"] = "apri la finestra delle opzioni"
L["turn the addon on"] = "attiva l'add-on"
L["turn it off"] = "disattivalo"
L["hide the prompt for a while -- 15 minutes unless you say"] = "nascondi il riquadro per un po' -- 15 minuti, se non indichi altro"
L["preview the prompt with a mock candidate"] = "mostra un'anteprima del riquadro con un candidato finto"
L["the favour ledger: who buffed you, what you gave back, and who you buffed"] = "il registro dei favori: chi ti ha dato un beneficio, cosa hai ricambiato e a chi hai dato un beneficio"
L["what this addon does, and the one thing it needs from you"] = "cosa fa questo add-on, e l'unica cosa che ti chiede"
L["make a /click macro for your action bar"] = "crea una macro /click per la barra delle azioni"
L["unlock the prompt so it can be dragged"] = "sblocca il riquadro per poterlo trascinare"
L["lock it again -- an unlocked prompt never casts"] = "bloccalo di nuovo -- un riquadro sbloccato non lancia mai niente"
L["list who is never offered anything, or put somebody on that list"] = "elenca chi non viene mai proposto, o aggiungi qualcuno agli esclusi"
L["take somebody off the never-offer list"] = "togli qualcuno dagli esclusi"
L["switch handing your target back after buffing on or off"] = "attiva o disattiva il ripristino del bersaglio dopo aver dato un beneficio"
L["switch the chat lines about who buffed you on or off"] = "attiva o disattiva le righe in chat su chi ti ha dato un beneficio"
L["copy these settings as one line of text"] = "copia queste impostazioni come un'unica riga di testo"
L["use settings somebody exported, or undo the last import"] = "usa le impostazioni esportate da qualcuno, o annulla l'ultima importazione"
L["what your class and this build allow"] = "cosa permettono la tua classe e questo client"
L["the last few things that broke"] = "gli ultimi errori"
L["tools for testing the addon on this client: the click log, try, look and forms"] = "strumenti per testare l'add-on su questo client: il log dei clic, try, look e forms"
L["log what the button does when clicked"] = "scrivi in chat cosa fa il pulsante quando ci fai clic"
L["run any macro text from the prompt"] = "esegui qualsiasi testo di macro dal riquadro"
L["dump every API answer for a unit"] = "mostra ogni risposta dell'API per un'unità"
L["example macros to try"] = "esempi di macro da provare"
L["Manners commands:"] = "Comandi di Manners:"
L["|cffffd100/mnr|r works in place of |cffffd100/manners|r in all of them."] = "|cffffd100/mnr|r funziona al posto di |cffffd100/manners|r in tutti i comandi."
L["try cleared -- the normal cast takes effect when this fight ends; until then a press runs the macro already on the button."] = "try annullato -- il lancio normale torna quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante."
L["try cleared -- back to the normal cast."] = "try annullato -- si torna al lancio normale."
L["try armed: |cff80ff80%s|r"] = "try attivato: |cff80ff80%s|r"
L["|cffff8080not armed for now:|r %s."] = "|cffff8080per ora non attivato:|r %s."
L["expands to: |cffffffff%s|r"] = "diventa: |cffffffff%s|r"
L["%d characters -- %d over the %d a macro body holds. The client will cut it, and what runs is not what is printed above."] = "%d caratteri -- %d oltre i %d che il testo di una macro può contenere. Il client lo taglierà, e ciò che viene eseguito non è ciò che vedi qui sopra."
L["It takes effect when this fight ends; until then a press runs the macro already on the button. |cffffd100/manners try|r with nothing clears it."] = "Ha effetto quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante. |cffffd100/manners try|r da solo lo annulla."
L["The prompt arms it once they have one. |cffffd100/manners try|r with nothing clears it."] = "Il riquadro lo attiva appena il giocatore ne ha uno. |cffffd100/manners try|r da solo lo annulla."
L["Click the prompt to run it. |cffffd100/manners try|r with nothing clears it."] = "Fai clic sul riquadro per eseguirlo. |cffffd100/manners try|r da solo lo annulla."
L["Targeting forms, for /manners try:"] = "Modi di indicare il bersaglio, per /manners try:"
L["(on yourself)"] = "(su di te)"
L["Tokens: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} is what a debt is filed under, {aim} is what a targeting line wants. Use \\n for a new line."] = "Segnaposto: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} è il nome sotto cui si registra un debito, {aim} è ciò che serve a una riga di bersaglio. Usa \\n per andare a capo."
L["the favour ledger did not load -- reinstalling Manners should bring it back."] = "il registro dei favori non si è caricato -- reinstallare Manners dovrebbe riportarlo."
L["unlocked -- it can be dragged once this fight ends; until then a press still casts what the fight froze. Then |cffffd100/manners lock|r."] = "sbloccato -- potrai trascinarlo quando finisce questo combattimento; fino ad allora un clic lancia ancora ciò che il combattimento ha congelato. Poi |cffffd100/manners lock|r."
L["unlocked -- it can be dragged once this fight ends; nothing is armed meanwhile. Then |cffffd100/manners lock|r."] = "sbloccato -- potrai trascinarlo quando finisce questo combattimento; nel frattempo il pulsante è vuoto. Poi |cffffd100/manners lock|r."
L["unlocked -- drag the prompt, then |cffffd100/manners lock|r."] = "sbloccato -- trascina il riquadro, poi |cffffd100/manners lock|r."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- |cffffd100/manners on|r first."] = "sbloccato, ma l'add-on è |cffff8080disattivato|r, quindi non c'è nessun riquadro da trascinare -- prima |cffffd100/manners on|r."
L["locked."] = "bloccato."
L["hand your target back after buffing: |cff00ff00on|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "ripristino del bersaglio dopo un beneficio: |cff00ff00attivato|r -- ha effetto quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante."
L["hand your target back after buffing: |cffff0000off|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "ripristino del bersaglio dopo un beneficio: |cffff0000disattivato|r -- ha effetto quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante."
L["hand your target back after buffing: |cff00ff00on|r"] = "ripristino del bersaglio dopo un beneficio: |cff00ff00attivato|r"
L["hand your target back after buffing: |cffff0000off|r"] = "ripristino del bersaglio dopo un beneficio: |cffff0000disattivato|r"
L["click logging: |cff00ff00on|r"] = "log dei clic: |cff00ff00attivato|r"
L["click logging: |cffff0000off|r"] = "log dei clic: |cffff0000disattivato|r"
L["verbose: |cff00ff00on|r -- a line in your own chat when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed"] = "verbose: |cff00ff00attivato|r -- una riga nella tua chat quando qualcuno ti dà un beneficio, quando un favore viene considerato ricambiato, e quando un clic fallisce, viene saltato o lascia un favore da ricambiare"
L["verbose: |cffff0000off|r"] = "verbose: |cffff0000disattivato|r"
L["enabled."] = "attivato."
L["disabled."] = "disattivato."
L["nobody is on your never-offer list. Shift-right-click the prompt to put whoever it is showing on it."] = "non c'è nessuno tra i tuoi esclusi. Fai Maiusc+clic destro sul riquadro per aggiungere agli esclusi il giocatore che mostra."
L["never offered anything unless they buff you: %s"] = "mai proposti, a meno che non ti diano un beneficio: %s"
L["say who: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lists everybody on the list."] = "indica chi: |cffffd100/manners allow Name|r. |cffffd100/manners never|r elenca tutti gli esclusi."
L["|cffffffff%s|r can be offered again."] = "|cffffffff%s|r può di nuovo essere proposto."
L["nobody called %s is on your never-offer list."] = "tra i tuoi esclusi non c'è nessuno che si chiami %s."
L["snooze takes a number of minutes from 1 to %d, or off -- for example |cffffd100/manners snooze 15|r or |cffffd100/manners snooze 1h|r."] = "snooze accetta un numero di minuti da 1 a %d, oppure off -- per esempio |cffffd100/manners snooze 15|r o |cffffd100/manners snooze 1h|r."
L["your settings are in the box under |cffffd100Share as text|r on the Profiles tab of the options -- click in it, select all and copy."] = "le tue impostazioni sono nella casella sotto |cffffd100Condividi come testo|r nella scheda Profili delle opzioni -- fai clic nella casella, seleziona tutto e copia."
L["this string is too long to be imported back -- a very long phrase box under What I say is the usual cause. Shorten it if you want to share these settings."] = "questa stringa è troppo lunga per essere reimportata -- di solito la causa è una casella delle frasi molto lunga nella scheda Cosa dico. Accorciala se vuoi condividere queste impostazioni."
L["paste the settings string into the box under |cffffd100Share as text|r on the Profiles tab, or type |cffffd100/manners import|r followed by it."] = "incolla la stringa delle impostazioni nella casella sotto |cffffd100Condividi come testo|r nella scheda Profili, oppure scrivi |cffffd100/manners import|r seguito dalla stringa."
L["type |cffffd100/manners import|r followed by a settings string."] = "scrivi |cffffd100/manners import|r seguito da una stringa delle impostazioni."
L["Tools for testing Manners on this client:"] = "Strumenti per testare Manners su questo client:"
L["nothing has broken this session."] = "in questa sessione non è andato storto niente."
L["|cffffd100the last %d of %d|r |cff808080(%d kept)|r:"] = "|cffffd100gli ultimi %d di %d|r |cff808080(%d conservati)|r:"
L["|cffffd100the last %d of %d|r:"] = "|cffffd100gli ultimi %d di %d|r:"
L["Flavour.lua did not load -- check the toc's file list"] = "Flavour.lua non si è caricato -- controlla l'elenco dei file del toc"
L["your own buff: not offered -- %s is switched off."] = "il tuo beneficio personale: non proposto -- l'opzione %s è disattivata."
L["|cffff4040this client has never heard of %s|r -- Manners has the wrong spell ids for %s on %s. Please report this line."] = "|cffff4040questo client non conosce %s|r -- Manners ha gli ID incantesimo sbagliati per %s su %s. Segnala questa riga, per favore."
L["owes returning: |cffffffff%s|r (%ds left, buffed you %ds ago)"] = "da ricambiare: |cffffffff%s|r (%d s rimasti, ti ha dato un beneficio %d s fa)"
L["not watching for favours -- Manners is switched off."] = "nessun controllo dei favori -- Manners è disattivato."
L["not watching for favours -- |cffffd100People who buff me|r is switched off."] = "nessun controllo dei favori -- l'opzione |cffffd100Chi mi dà un beneficio|r è disattivata."
L["nobody has buffed you recently."] = "nessuno ti ha dato un beneficio di recente."
L["your own buff: offered to you when you are missing it."] = "il tuo beneficio personale: proposto quando non ce l'hai."
L["your own buff: nothing you cast goes on yourself alone."] = "il tuo beneficio personale: niente di ciò che lanci va solo su di te."
L["|cffff8080own buffs: last scan not believed (%s)|r -- %d read, baseline %d"] = "|cffff8080benefici su di te: ultima scansione non attendibile (%s)|r -- %d letti, riferimento %d"
L["|cffffd100own buffs: baseline not settled|r -- %d read, waiting for a second scan to agree"] = "|cffffd100benefici su di te: riferimento non stabilito|r -- %d letti, in attesa di una seconda scansione che confermi"
L["own buffs: %d read, baseline %d"] = "benefici su di te: %d letti, riferimento %d"
L["thank with an emote: |cff00ff00on|r"] = "ringraziamento con emote: |cff00ff00attivato|r"
L["thank with an emote: |cffff0000off|r"] = "ringraziamento con emote: |cffff0000disattivato|r"
L["last thanked: |cffffffff%s|r, %ds ago (the game answered %s)"] = "ultimo ringraziamento: |cffffffff%s|r, %d s fa (risposta del gioco: %s)"
L["last not thanked: |cffffffff%s|r, %ds ago (%s)"] = "ultimo ringraziamento saltato: |cffffffff%s|r, %d s fa (%s)"
L["switched OFF on this profile -- nothing is recorded or offered; /manners on"] = "DISATTIVATO in questo profilo -- non si registra né si propone niente; /manners on"
L["prompt is UNLOCKED -- it will not buff anyone until you /manners lock"] = "il riquadro è SBLOCCATO -- non darà benefici a nessuno finché non scrivi /manners lock"
L["|cffffd100snoozed until %s|r -- no prompt until then; /manners snooze off ends it"] = "|cffffd100in pausa fino alle %s|r -- nessun riquadro fino ad allora; /manners snooze off la termina"
L["|cffffd100mounted|r -- Not while mounted keeps the prompt away until you get off"] = "|cffffd100in sella|r -- l'opzione Non in sella tiene nascosto il riquadro finché non scendi dalla cavalcatura"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only your own buff and people who buffed you or asked are offered"] = "|cffffd100risparmio di mana|r -- finché non torni al %d%% di mana, il riquadro propone solo il tuo beneficio personale e chi ti ha dato un beneficio o te l'ha chiesto"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only people who buffed you or asked are offered"] = "|cffffd100risparmio di mana|r -- finché non torni al %d%% di mana, il riquadro propone solo chi ti ha dato un beneficio o te l'ha chiesto"
L["|cffffd100ready check|r -- your party or raid comes first until the pull"] = "|cffffd100appello|r -- il tuo gruppo o la tua incursione ha la precedenza fino all'inizio del combattimento"
L["|cffffd100raid groups|r -- in a raid, only groups %s are offered unasked"] = "|cffffd100gruppi dell'incursione|r -- in un'incursione, solo i gruppi %s vengono proposti senza che lo chiedano"
L["|cffffd100raid groups|r -- every group is unticked, so in a raid nobody is offered unasked"] = "|cffffd100gruppi dell'incursione|r -- nessun gruppo è spuntato, quindi in un'incursione nessuno viene proposto senza che lo chieda"
L["|cffff8080/manners try is armed:|r %s -- clear it with a bare /manners try"] = "|cffff8080/manners try è attivato:|r %s -- annullalo con /manners try da solo"
L["queue now: %d"] = "in coda ora: %d"
L["queue if switched on: %d"] = "in coda se attivato: %d"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "non esiste |cffffd100/manners %s|r -- intendevi |cffffd100/manners %s|r? |cffffd100/manners help|r li elenca tutti."
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "non esiste |cffffd100/manners %s|r -- intendevi |cffffd100/manners %s|r? |cffffd100/manners dev|r elenca gli strumenti di test."
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "Grazie di cuore, {name}! Alla forgia il primo giro lo offro io."
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "Grazie assai, {name}. Ora hai un amico nella montagna."
L["Thank ye, {name}! I'd have been fine without it, mind. But thank ye."] = "Grazie, {name}! Me la sarei cavata anche senza, sia chiaro. Ma grazie."
L["Bless ye, {name}! I'd hug ye, but ye'd be needin' a healer after."] = "Evviva, {name}! Ti abbraccerei, ma poi ti servirebbe un guaritore."
L["Paid back already, {name}. Quicker than I've ever settled a bar tab."] = "Già ricambiato, {name}. Mai saldato un conto all'osteria così in fretta."
L["I'll tell this at the Thunderbrew like ye saved me life, {name}. Thank ye!"] = "A Kharanos lo racconterò come se mi avessi salvato la vita, {name}. Grazie!"
L["Grand, {name}! I'd carve ye a statue, but this is quicker."] = "Magnifico, {name}! Ti scolpirei una statua, ma così si fa prima."
L["The Titans made us of stone, {name}, but that still touched me. Thank ye."] = "I Titani ci fecero di pietra, {name}, ma stavolta hai fatto breccia. Grazie."
L["Aye, {name}, ye only had to ask. Hold still now, like a good anvil."] = "Ma certo, {name}, bastava chiedere! Ora immobile, come una brava incudine."
L["Say no more, {name}. Stone and steel, here it comes."] = "Non dire altro, {name}. Pietra e acciaio, eccolo che arriva!"
L["Ask a dwarf fer help, {name}, and ye'll get it. Loudly."] = "Chiedi aiuto a un nano, {name}, e l'avrai. A pieni polmoni."
L["Right, {name}. Brace yerself; I do everything like I'm swingin' a hammer."] = "Bene, {name}. Tieniti forte: io faccio tutto come se brandissi un martello."
L["Aye, {name}, and a story about it ye didn't ask fer. Where to begin..."] = "Certo, {name}, con tanto di storia che non hai chiesto. Da dove comincio..."
L["One {buff}, pulled fresh like a proper pint, {name}."] = "{buff} alla spina, {name}. Spillatura a regola d'arte."
L["Done, {name}. Dwarven work: over-built, under-priced and guaranteed."] = "Fatto, {name}. Lavoro nanico: sovradimensionato, sottocosto e garantito."
L["Here, {name}, a wee somethin' to keep ye on yer feet. Wee, like me."] = "Tieni, {name}, un aiutino per tenerti in piedi. Piccolo, come me."
L["Off ye go, {name}, steady as the mountain."] = "Va' pure, {name}, con passo saldo come la montagna."
L["Here, {name}. Ale's for after; this is for before."] = "Tieni, {name}. La birra è per dopo; questo è per prima."
L["Magni turned to diamond fer the cause, {name}. This is the cheaper option."] = "Magni diventò diamante per la causa, {name}. Questa è la versione economica."
L["A dwarf's got yer back, {name}. Well, yer knees. Close enough."] = "Un nano ti copre le spalle, {name}. Be', le ginocchia. Quasi uguale."
L["If a trogg bothers ye, {name}, tell it a dwarf sent ye. Then run."] = "Se un trogg ti dà noia, {name}, digli che ti manda un nano. Poi scappa."
L["If it wears off, {name}, give it a good thump. That's how we fix everything."] = "Se svanisce, {name}, dagli una bella botta. Noi aggiustiamo tutto così."
L["Take this, {name}. I'd give ye some stubbornness too, but I'm usin' all mine."] = "Prendi, {name}. Ti darei anche un po' della mia testa dura, ma mi serve tutta."
L["Stone and hammer keep ye, cousin {name}!"] = "Pietra e martello ti proteggano, {name}! Siamo della stessa roccia."
L["Three Hammers, one round, cousin {name}!"] = "Tre Martelli, un giro in famiglia, {name}!"
L["Yer cousin's cousin married mine, {name}, I'd wager. It's a small mountain."] = "Tuo cugino di terzo grado avrà sposato il mio, {name}. La montagna è piccola."
L["Two dwarves together, {name}. Pity whatever's standin' in our way."] = "Due nani insieme, {name}. Povero chi ci sbarra la strada."
L["Stand behind me, {name}. Aye, I know. Crouch a bit."] = "Mettiti dietro di me, {name}. Sì, lo so. Abbassati un po'."
L["Right, {name}: I take the front, ye take the loot, and we argue after."] = "Allora, {name}: io sto davanti, tu prendi il bottino, e poi litighiamo."
L["If I start singin', {name}, the fight's gone well. Or very badly."] = "Se comincio a cantare, {name}, va alla grande. O malissimo."
L["Dwarves never leave a mate behind, {name}. Nor a keg. Mates first, mind."] = "Un nano non lascia indietro un compagno, {name}. Né un barile. Nell'ordine."
L["Beards out, {name}! Them without beards, look fierce. It's nearly as good."] = "Barbe al vento, {name}! Chi non ce l'ha, sguardo feroce. Funziona quasi."
L["Mornin', {name}! Too early for ale. Almost. Have this first."] = "'Giorno, {name}! Troppo presto per la birra. Quasi. Prima questo."
L["Up with the forge fires, {name}! A dwarf's day starts with a hammer and this."] = "Si accendono le forge, {name}! La giornata di un nano: martello, e questo."
L["Early, {name}? Nonsense. The mine's been open two hours. Here."] = "Presto, {name}? Macché. La miniera è aperta da due ore. Tieni."
L["My thanks, {name}. Let me return the kindness before a bard gets it wrong."] = "Ti ringrazio, {name}. Ricambio, prima che un bardo la racconti storta."
L["Kindly done, {name}. Let no one say we forget a friend."] = "Molto gentile, {name}. Nessuno dirà che dimentichiamo gli amici."
L["Thank you, {name}. I'd knight you, but apparently I 'need permission'."] = "Grazie, {name}. Ti farei cavaliere, ma pare che mi serva il 'permesso'."
L["Repaid on the spot, {name}. In Stormwind that'd take three forms and a stamp."] = "Ricambiato all'istante, {name}. A Roccavento: tre moduli e una marca da bollo."
L["Thanks, {name}. I'd pay in gold, but Stormwind still owes the stonemasons."] = "Grazie, {name}. Pagherei in oro, ma Roccavento è in debito con gli scalpellini."
L["Much obliged, {name}. Mother said always return a kindness. And the dish."] = "Grazie, {name}. Mamma diceva: ricambia sempre una gentilezza. E riporta la teglia."
L["Thank you, {name}. Consider the scales balanced, by royal decree. Mine."] = "Grazie, {name}. Conti pari, per decreto reale. Il mio."
L["You shame me, {name}; I should have thought of it first. Allow me."] = "Mi hai fatto fare brutta figura, {name}: dovevo pensarci io. Permetti."
L["Of course, {name}. Hold still and look heroic; it helps the bards."] = "Certo, {name}. Resta immobile e fa' la faccia da eroe: aiuta i bardi."
L["Right away, {name}. Keep your shield high."] = "Subito, {name}. Tieni alto lo scudo."
L["More work? Gladly, {name}. It beats the lumber mill."] = "Altro lavoro? Volentieri, {name}. Meglio della segheria."
L["Of course, {name}. Humans excel at helping and overpromising. This is helping."] = "Certo, {name}. Noi umani aiutiamo e promettiamo mari e monti. Questo è l'aiuto."
L["Certainly, {name}. Humans are quick learners; I learned this one yesterday."] = "Certamente, {name}. Noi umani impariamo in fretta: questo l'ho imparato ieri."
L["Hold still, {name}, like a statue in the Valley of Heroes. You'd fit right in."] = "Non muoverti, {name}, come una statua nella Valle degli Eroi. Ci staresti bene."
L["Right away, {name}. The Light helps those who ask. So do I, and I'm quicker."] = "Subito, {name}. La Luce aiuta chi chiede. Anch'io, e faccio prima."
L["The road ahead is long, {name}. This won't shorten it, but it'll help."] = "La strada è lunga, {name}. Questo non la accorcia, ma aiuta."
L["Fair winds and following seas, {name}."] = "Buon vento e mare calmo, {name}."
L["Take this, {name}. Elves have centuries to be generous; I've got fifty years."] = "Prendi, {name}. Gli elfi hanno secoli per essere generosi; io ho cinquant'anni."
L["A little something, {name}. Don't tell the guards; they'll all want one."] = "Un pensierino, {name}. Non dirlo alle guardie, o lo vorranno tutte."
L["Here, {name}. If a kobold asks, you don't have a candle."] = "Tieni, {name}. Se un coboldo te lo chiede, candele non ne hai."
L["For you, {name}. A human gift: well meant, hastily made, surprisingly sturdy."] = "Per te, {name}. Dono umano: buone intenzioni, fatto in fretta, robusto a sorpresa."
L["Mind the murlocs, {name}. Take this; I've seen what they do to a picnic."] = "Occhio ai murloc, {name}. Prendi: ho visto cosa fanno a un picnic."
L["Every road needs a hero, {name}. Today it's me, apparently. Take this."] = "Ogni strada ha bisogno di un eroe, {name}. Oggi tocca a me, pare. Prendi."
L["Arathor's children stand together, {name}."] = "I figli di Arathor restano uniti, {name}."
L["A fellow human, {name}! Quick, let's found a kingdom before lunch."] = "Tra umani, {name}! Presto, fondiamo un regno prima di pranzo."
L["Stormwind or Boralus, {name}, we'll both complain about the weather."] = "Roccavento o Boralus, {name}, ci lamenteremo comunque del tempo."
L["Human to human, {name}: no, I don't know why everything happens to us either."] = "Da umano a umano, {name}: no, non so neanch'io perché capitano tutte a noi."
L["Keep close, {name}. Humans have always won by outnumbering things."] = "Stammi vicino, {name}. Gli umani vincono da sempre perché sono di più."
L["Stay in formation, {name}. We haven't got one, but stay in it anyway."] = "Mantieni la formazione, {name}. Non ne abbiamo una, ma mantienila lo stesso."
L["I'll draw up a plan, {name}, and then we can all ignore it together."] = "Preparo un piano, {name}, così poi possiamo ignorarlo tutti insieme."
L["Every hero in the songs had friends, {name}. Nobody sings about them. I will."] = "Ogni eroe delle ballate aveva degli amici, {name}. Nessuno li canta. Io sì."
L["Shields up, {name}. Stormwind taught me to march; nobody taught me to stop."] = "Scudi alzati, {name}. Roccavento mi ha insegnato a marciare; a fermarmi, nessuno."
L["Ishnu-alah, {name}. Returned the same day, which for a kaldorei is rushing."] = "Ishnu-alah, {name}. Ricambio in giornata: per un kaldorei è andare di corsa."
L["Thank you, {name}. Elune smiles on the generous."] = "Grazie, {name}. Elune sorride a chi è generoso."
L["Thank you, {name}. Even the wisps glow brighter, and they're hard to impress."] = "Grazie, {name}. Anche i fuochi fatui brillano di più, e non è facile stupirli."
L["Elune saw that, {name}. She sees everything, so I had best return it."] = "Elune ha visto, {name}. Lei vede tutto, quindi meglio che ricambi."
L["Thank you, {name}. Returned before I nap for a century or two."] = "Grazie, {name}. Ricambio prima del mio pisolino di un paio di secoli."
L["Thank you, {name}. The Ancients will hear of this. They're dreadful gossips."] = "Grazie, {name}. Gli Antichi lo verranno a sapere. Sono dei gran pettegoli."
L["Thank you, {name}. I'll tell the Sentinels to stop aiming at you."] = "Grazie, {name}. Dirò alle Sentinelle di smettere di prenderti di mira."
L["My people never hurry, {name}. For you, an exception."] = "Il mio popolo non ha fretta, {name}. Per te, un'eccezione."
L["Gladly, {name}. Be still, and let the moonlight find you."] = "Con gioia, {name}. Resta immobile e lascia che la luna ti trovi."
L["Of course, {name}. Elune's blessings are meant to be shared."] = "Certo, {name}. Le benedizioni di Elune vanno condivise."
L["At last, {name}! I've waited ten thousand years for someone to ask."] = "Finalmente, {name}! Sono diecimila anni che aspetto che qualcuno chieda."
L["No riddle, no omen from Elune, {name}. Just a plain yes, for once."] = "Niente enigmi, niente presagi di Elune, {name}. Solo un sì, per una volta."
L["Of course, {name}. Ask in Darnassian next time and I'll add a bow."] = "Certo, {name}. Chiedilo in darnassiano e ci aggiungo un inchino."
L["Elune already said yes, {name}. I'm merely catching up."] = "Elune ha già detto di sì, {name}. Io mi sto solo adeguando."
L["Of course, {name}. Stand still and pretend you're a tree. It helps."] = "Certo, {name}. Resta immobile e fingi di essere un albero. Aiuta."
L["Elune-adore, {name}. Walk softly; the trees are light sleepers."] = "Elune-adore, {name}. Cammina lieve: gli alberi hanno il sonno leggero."
L["May the forest shelter you, {name}, wherever you roam."] = "Che la foresta ti protegga, {name}, ovunque tu vada."
L["A gift from the shadows, {name}. No, don't look. You won't find me."] = "Un dono dalle ombre, {name}. No, non guardarti intorno. Non mi troverai."
L["Elune lights your path, {name}. I'm merely holding the lantern."] = "Elune illumina il tuo cammino, {name}. Io reggo solo la lanterna."
L["The owls pointed you out, {name}. They have strong opinions. Here."] = "I gufi mi hanno indicato te, {name}. Hanno le idee chiare. Tieni."
L["Tyrande would insist, {name}, and nobody argues with Tyrande."] = "Tyrande insisterebbe, {name}, e nessuno discute con Tyrande."
L["Take this, {name}. The last one went to a hippogryph. It was less grateful."] = "Prendi, {name}. L'ultimo è andato a un ippogrifo. È stato meno riconoscente."
L["Mind the wildlife, {name}. Half of it is a druid, and all of it is watching."] = "Occhio alla fauna, {name}. Metà sono druidi, e tutti ti osservano."
L["Ishnu-alah, {name}. Elune keeps her children close."] = "Ishnu-alah, {name}. Elune tiene vicini i suoi figli."
L["Of course I saw you, {name}. It takes a kaldorei to spot a kaldorei."] = "Certo che ti ho visto, {name}. Solo un kaldorei scova un kaldorei."
L["One kaldorei to another, {name}: we lost a tree, never each other."] = "Da kaldorei a kaldorei, {name}: perso un albero, mai l'un l'altro."
L["A kaldorei never leaves kin in the dark, {name}. Unless it's for cover."] = "Un kaldorei non lascia i suoi al buio, {name}. Salvo per nascondersi."
L["Quick one, {name}? By kaldorei reckoning we'll be done before we start."] = "Una cosa veloce, {name}? Per un kaldorei, finiamo prima di cominciare."
L["I'll be the one you can't see, {name}. That's not a mistake; that's the plan."] = "Io sarò l'ombra che non vedi, {name}. Non è un errore: è il piano."
L["Elune watches the whole party, {name}. I'm just the one who waves at her."] = "Elune veglia su tutto il gruppo, {name}. Io mi limito a salutarla."
L["Ten thousand years of companions, {name}. You lot rank rather high."] = "In diecimila anni di compagni, {name}, voi siete in zona podio."
L["Stay close, {name}. We kaldorei misplaced two World Trees. Not you, though."] = "Stammi vicino, {name}. Noi kaldorei abbiamo smarrito due Alberi del Mondo. Te no."
L["The moon's up, {name}. For a kaldorei, this is the middle of the morning."] = "È sorta la luna, {name}. Per un kaldorei è metà mattina."
L["Everyone sensible is asleep, {name}. Elune and I prefer it this way."] = "Le persone assennate dormono, {name}. Elune e io preferiamo così."
L["Moonlight suits you, {name}. This is merely a second layer."] = "Il chiaro di luna ti dona, {name}. Questo è solo un secondo strato."
L["Morning, {name}. My people slept through these for millennia. I'm adapting."] = "Per millenni il mio popolo ha dormito a quest'ora, {name}. Mi sto adattando."
L["Dawn, {name}. Elune's gone to bed, so I'm covering for her."] = "Alba, {name}. Elune è andata a letto: la copro io."
L["The sun's up, {name}, and so, reluctantly, am I."] = "Il sole si è alzato, {name}, e io con lui. Controvoglia."
L["The shadows remember kindness, {name}. So do I."] = "Le ombre ricordano la gentilezza, {name}. E anch'io."
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "Ti ringrazio, {name}. I ren'dorei non dimenticano una gentilezza."
L["Thank you, {name}. The voices approve of you, which is frankly alarming."] = "Grazie, {name}. Le voci ti approvano, il che è francamente allarmante."
L["Thank you, {name}. Few give gifts to someone who glows this ominously."] = "Grazie, {name}. Pochi fanno doni a chi brilla in modo così inquietante."
L["Kindness is rare in the Void, {name}. I'll return yours before it notices."] = "La gentilezza è rara nel Vuoto, {name}. Ricambio la tua prima che se ne accorga."
L["Silvermoon threw us out, {name}. People like you make it hard to mind."] = "Lunargenta ci ha cacciati, {name}. Con gente come te, è difficile rimpiangerla."
L["Returned in full, {name}. It may be slightly purple. That's normal."] = "Ricambiato per intero, {name}. Potrebbe essere un po' viola. È normale."
L["The Void only takes, {name}. I, however, give back."] = "Il Vuoto prende e basta, {name}. Io, invece, restituisco."
L["As you wish, {name}. The shadows answer kindly today."] = "Come desideri, {name}. Oggi le ombre sono benevole."
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "Consideralo fatto, {name}. Il Vuoto obbedisce a noi, non il contrario."
L["Certainly, {name}. The whispers said no, so it's an easy yes."] = "Certo, {name}. I sussurri hanno detto di no, quindi è un sì facile."
L["Of course, {name}. One {buff}, lightly seasoned with the Void."] = "Certo, {name}. Ecco {buff}, con Vuoto quanto basta."
L["Of course, {name}. Hold still; the shadows are shy with strangers."] = "Certo, {name}. Non muoverti: le ombre sono timide con gli sconosciuti."
L["Gladly, {name}. Ren'dorei manners: the Void waits its turn."] = "Volentieri, {name}. Galateo ren'dorei: il Vuoto fa la fila."
L["Asked so nicely, {name}? The Void never says please. Here."] = "Che gentilezza, {name}! Il Vuoto non dice mai per favore. Tieni."
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "Un tocco d'ombra per te, {name}. Del tutto sicuro. Quasi."
L["Walk carefully in the dark places, {name}."] = "Cammina con cautela nei luoghi oscuri, {name}."
L["A little something from the Telogrus Rift, {name}. It's cleaner than it sounds."] = "Un pensierino dalla Faglia di Telogrus, {name}. È più pulito di quanto sembri."
L["Take this, {name}. Any tentacles you see are purely decorative."] = "Prendi, {name}. Eventuali tentacoli sono puramente decorativi."
L["The shadows asked after you, {name}. I told them to mind their manners."] = "Le ombre hanno chiesto di te, {name}. Ho detto loro di comportarsi bene."
L["Here, {name}. We walked into the Void so you wouldn't have to."] = "Tieni, {name}. Siamo entrati nel Vuoto perché tu non dovessi farlo."
L["I checked your shadow, {name}. Nothing lurking. Take this anyway."] = "Ho controllato la tua ombra, {name}. Nessuno in agguato. Prendi comunque."
L["Umbric sends his regards, {name}. He doesn't, but he would."] = "Umbric ti manda i suoi saluti, {name}. Non è vero, ma lo farebbe."
L["We ren'dorei look after our own, {name}."] = "Noi ren'dorei ci prendiamo cura dei nostri, {name}."
L["Silvermoon's loss, {name}. We're doing splendidly without it."] = "Peggio per Lunargenta, {name}. Senza di lei ce la passiamo benissimo."
L["Your whispers and mine should really meet sometime, {name}."] = "I tuoi sussurri e i miei dovrebbero conoscersi, prima o poi, {name}."
L["Two ren'dorei in one place, {name}. Quick, look brooding. It's expected."] = "Due ren'dorei insieme, {name}. Presto, aria tenebrosa: se l'aspettano tutti."
L["Stay close, {name}. The whispers are much quieter in company."] = "Stammi vicino, {name}. In compagnia i sussurri abbassano la voce."
L["If the shadows start giving orders, {name}, ignore them. I usually do."] = "Se le ombre cominciano a dare ordini, {name}, ignorale. Io di solito lo faccio."
L["Keep an eye on my shadow, {name}. It wanders off when there's a fight."] = "Tieni d'occhio la mia ombra, {name}. Quando c'è da combattere se la svigna."
L["If I start glowing purple, {name}, carry on. It only means I'm keen."] = "Se brillo di viola, {name}, vai avanti. Vuol dire solo che sono in vena."
L["We ren'dorei make fine companions, {name}. We bring our own dark to hide in."] = "Noi ren'dorei siamo ottima compagnia, {name}: il buio ce lo portiamo da casa."
L["Night suits the ren'dorei, {name}. We match the decor."] = "La notte ci dona, {name}. Siamo in tinta con l'arredo."
L["The shadows are longest now, {name}, and in a very generous mood."] = "Ora le ombre sono più lunghe, {name}, e di umore molto generoso."
L["Late, {name}? The whispers love a late hour. Lately, so do I."] = "È tardi, {name}? I sussurri amano le ore piccole. E ormai anch'io."
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "Grazie, {name}! Gentilezza ricevuta, catalogata e restituita!"
L["Reciprocity engaged! Much obliged, {name}."] = "Reciprocità attivata! Grazie mille, {name}."
L["By my calculations, {name}, you're owed exactly one {buff}."] = "Calcoli alla mano, {name}, ti spetta {buff}. Né più né meno."
L["Thanks, {name}! I'd build you a thank-you machine, but it'd explode."] = "Grazie, {name}! Ti costruirei una macchina per dire grazie, ma esploderebbe."
L["Thank you, {name}! This calls for a celebration. Stand back, I'll build one."] = "Grazie, {name}! Qui ci vuole una festa. Indietro, ne costruisco una."
L["You're too kind, {name}! Returning the favour took only four schematics."] = "Troppo gentile, {name}! Ricambiare mi è costato solo quattro schemi."
L["Drat, {name}! I was going to invent gratitude, but you beat me to it."] = "Accidenti, {name}! Stavo per inventare la gratitudine, e mi hai preceduto."
L["Oh, {name}, how kind! My heart's doing that whirring thing again."] = "Oh, {name}, che gentile! Il mio cuore fa di nuovo quel ronzio."
L["Request received, {name}! Processing... done!"] = "Richiesta ricevuta, {name}! Elaborazione... fatto!"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "Un potenziamento in arrivo, {name}! Non muoverti, devo calibrare."
L["Of course, {name}! I built a machine for this. It's in pieces, so: by hand."] = "Certo, {name}! Ho costruito una macchina apposta. È in pezzi, quindi: a mano."
L["Certainly, {name}! Stand on the X. There's no X. Stand anywhere."] = "Certo, {name}! Mettiti sulla X. Non c'è una X. Mettiti dove vuoi."
L["Right away, {name}! Goggles on. Not for you, I just like them."] = "Subito, {name}! Su gli occhialoni. Non servono: mi piacciono e basta."
L["{buff}, {name}? Simple in theory AND practice. Suspicious!"] = "{buff}, {name}? Semplice in teoria E in pratica. Sospetto!"
L["Happy to, {name}! Keep hands, feet and eyebrows well clear."] = "Volentieri, {name}! Mani, piedi e sopracciglia ben lontani."
L["Hold still, {name}, this is perfectly safe. Probably!"] = "Non muoverti, {name}, è perfettamente sicuro. Probabilmente!"
L["Science says you need this, {name}. Who am I to argue?"] = "La scienza dice che ti serve, {name}. Chi sono io per contraddirla?"
L["A small upgrade for you, {name}. No cogs required."] = "Un piccolo potenziamento per te, {name}. Senza ingranaggi."
L["Take it, {name}, I've a spare. I've three spares of everything."] = "Prendi, {name}, ho il ricambio. Ho tre ricambi di tutto."
L["Try this, {name}! Version one had legs. Version two is much better."] = "Prova, {name}! La versione 1.0 aveva le gambe. La 2.0 va molto meglio."
L["The High Tinker says share our genius, {name}. Here's a sample!"] = "Il Gran Meccanista vuole genio condiviso, {name}. Eccone un assaggio!"
L["Gnomeregan Forever, {name}! This lasts rather less, but it's free."] = "Gnomeregan per sempre, {name}! Questo dura un po' meno, ma è gratis."
L["I'm small, {name}, but my gifts come full-sized. Here!"] = "Io sono tascabile, {name}, i miei doni no. Ecco!"
L["Don't worry, {name}! It worked on the chicken, and the chicken's thrilled."] = "Niente paura, {name}! Sul pollo ha funzionato, e il pollo è entusiasta."
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "Per Gnomeregan, {name}! Che bello parlare con qualcuno alla mia altezza."
L["A fellow gnome, {name}! I'll hold the schematic; you hold the bucket."] = "Tra gnomi, {name}! Io tengo lo schema, tu tieni il secchio."
L["Flesh or cogs, {name}, we're all gnomes. Some of us just need oiling."] = "Carne o ingranaggi, {name}, siamo tutti gnomi. Solo, qualcuno va oliato."
L["One gnome to another, {name}: you did turn the reactor off, didn't you?"] = "Da gnomo a gnomo, {name}: il reattore l'hai spento, vero?"
L["Party-wide calibration complete, {name}! Nobody touch anything shiny."] = "Gruppo calibrato, {name}! Nessuno tocchi niente che luccica."
L["I've run the numbers, {name}: with you here, we win. I rounded up."] = "Ho fatto i calcoli, {name}: con te qui, vinciamo. Ho arrotondato per eccesso."
L["If I shout 'duck', {name}, don't look for a duck. That went badly last time."] = "Se grido 'Bomba!', {name}, non è un complimento. L'ultima volta è finita male."
L["Formation, {name}: tall folk at the front, me somewhere safe and clever."] = "Formazione, {name}: gli alti davanti, io in un punto sicuro e geniale."
L["Everyone gets one, {name}! Standardised parts are the secret of a good machine."] = "Uno per tutti, {name}! I pezzi standard sono il segreto di una buona macchina."
L["Morning, {name}! Up since three. The toaster needed a new engine."] = "Buongiorno, {name}! In piedi dalle tre: il tostapane voleva un motore nuovo."
L["Good morning, {name}! The coffee's brewing itself. It learned how. Worrying."] = "Buongiorno, {name}! La moka si fa il caffè da sola. Ha imparato. Preoccupante."
L["Early start, {name}! Best ideas come before breakfast. So do the explosions."] = "Di buon'ora, {name}! Le idee migliori vengono prima di colazione. E le esplosioni."
L["The Light rewards kindness, {name}. I'm simply its fastest courier."] = "La Luce premia la gentilezza, {name}. Io consegno: corriere espresso."
L["Archenon poros, {name}. Your gift is returned."] = "Archenon poros, {name}. Ricambio il tuo dono."
L["Thanks, {name}. I'd offer a lift in the Exodar, but you've seen how it lands."] = "Grazie, {name}. Ti darei un passaggio sull'Exodar, ma hai visto come atterra."
L["A gift freely given, {name}. The naaru hum a little louder. Returned."] = "Un dono fatto col cuore, {name}. I Naaru ronzano un po' più forte. Ricambiato."
L["Kindly done, {name}. On Argus we'd have carved that in crystal. Here."] = "Gentile davvero, {name}. Su Argus l'avremmo inciso nel cristallo. Tieni."
L["Across a dozen worlds, {name}, kindness is the one tongue I never had to learn."] = "Dodici mondi, {name}, e la gentilezza è l'unica lingua che non ho dovuto imparare."
L["What a kindness, {name}. It almost makes up for the Legion. Almost."] = "Che gentilezza, {name}. Quasi mi ripaga della Legione. Quasi."
L["Thank you, {name}. I'd say it in Draenei, but that takes eleven minutes."] = "Grazie, {name}. Lo direi in draenei, ma ci vogliono undici minuti."
L["Of course, {name}. The naaru guide your steps; this puts a spring in them."] = "Certo, {name}. I Naaru guidano i tuoi passi; questo li rende più leggeri."
L["Gladly, {name}. The Light answers those who ask."] = "Con piacere, {name}. La Luce risponde a chi chiede."
L["Velen foresaw you asking, {name}. I foresaw saying yes."] = "Velen previde la tua richiesta, {name}. Io previdi il sì."
L["The Light is not rationed, {name}. Take as much as you like."] = "La Luce non è razionata, {name}. Prendine quanta ne vuoi."
L["Of course, {name}. I've outrun the Burning Legion; I can manage this."] = "Certo, {name}. Ho seminato la Legione Infuocata: questo è un gioco da ragazzi."
L["At once, {name}. Hooves planted, crystals humming, here it comes."] = "Subito, {name}. Zoccoli ben piantati, cristalli in risonanza... ecco!"
L["Gladly, {name}. I followed a talking crystal across the stars. This is easy."] = "Volentieri, {name}. Ho seguito un cristallo parlante tra le stelle. Questo è facile."
L["The Light is with you, {name}. Go in peace, or at least go prepared."] = "La Luce è con te, {name}. Va' in pace, o almeno con la guardia alta."
L["Walk in the Light, {name}. May it shelter you always."] = "Cammina nella Luce, {name}. Che ti protegga sempre."
L["Take this, {name}. My people always travel Light."] = "Prendi, {name}. Il mio popolo fa tutto alla Luce del sole."
L["Take this, {name}. The Legion is always coming. I'd know."] = "Prendi, {name}. La Legione arriva sempre. Lo so bene."
L["I'm out of miracles today, {name}. Will {buff} do?"] = "Oggi ho finito i miracoli, {name}. Va bene {buff}?"
L["For the road, {name}. Mine has been twenty-five thousand years long."] = "Per il viaggio, {name}. Il mio dura da venticinquemila anni."
L["Blessed by a naaru, {name}. Well, I stood near one. It still counts."] = "Con la benedizione di un Naaru, {name}. Be', ero lì accanto. Conta lo stesso."
L["Take this, {name}. It glows a bit. Everything we own does."] = "Prendi, {name}. Brilla un po'. Come tutto quello che abbiamo."
L["Archenon poros, {name}! The children of Argus look after one another."] = "Archenon poros, {name}! I figli di Argus si prendono cura l'uno dell'altro."
L["Home is wherever two draenei meet, {name}. Today, it's here."] = "Casa è ovunque si incontrino due draenei, {name}. Oggi, è qui."
L["Horns high, {name}. Two draenei, and nobody's mentioned the Legion. Progress."] = "Testa alta, {name}. Due draenei, e nessuno ha nominato la Legione. Progressi."
L["Tails up, {name}. Argus would be proud of what we've made of exile."] = "Coda alta, {name}. Argus sarebbe fiero di ciò che abbiamo fatto dell'esilio."
L["Stay near, {name}. I lost a world once; I'm keeping hold of this party."] = "Stammi vicino, {name}. Ho già perso un mondo: questo gruppo me lo tengo stretto."
L["Twenty-five thousand years on the run, {name}. Walking with friends is nicer."] = "Venticinquemila anni in fuga, {name}. Camminare con gli amici è più bello."
L["The naaru would call this a fellowship, {name}. I call it good luck."] = "I Naaru la chiamerebbero fratellanza, {name}. Io la chiamo fortuna."
L["I've watched worlds end, {name}. Whatever's ahead of us hardly worries me."] = "Ho visto finire dei mondi, {name}. Quello che ci aspetta non mi spaventa."
L["Stay together, {name}. The Light finds us easier when we're all in one place."] = "Restiamo uniti, {name}. La Luce ci trova più facilmente se siamo tutti insieme."
L["Much obliged, {name}. Gilneas never forgets a kindness, and nor does my nose."] = "Grazie infinite, {name}. Gilneas non dimentica una gentilezza. Il mio naso nemmeno."
L["Thank you, {name}. You have my gratitude, and my best howl."] = "Grazie, {name}. Hai la mia gratitudine, e il mio ululato migliore."
L["Thank you, {name}. If worgen had tails, mine would be wagging."] = "Grazie, {name}. Se i worgen avessero la coda, la mia scodinzolerebbe."
L["You've made a friend for life, {name}. Loyalty is rather our thing."] = "Amicizia a vita, {name}. La fedeltà è un po' il nostro forte."
L["The beast in me wants to growl, {name}. The Gilnean in me insists on thanks."] = "La bestia in me vuole ringhiare, {name}. Il gilneano insiste per un grazie."
L["Much appreciated, {name}. I'd shake your hand, but, claws. Here instead."] = "Molto apprezzato, {name}. Ti stringerei la mano, ma... artigli. Tieni questo."
L["We walled ourselves off for years, {name}. You make that look silly."] = "Anni chiusi dietro un muro, {name}. Con te sembra proprio una sciocchezza."
L["Obliged, {name}. You've earned a spot by the fire. The good spot."] = "Grazie, {name}. Ti spetta un posto vicino al fuoco. Quello buono."
L["Certainly, {name}. Hold still, I don't bite. Much."] = "Certamente, {name}. Non muoverti, non mordo. Non troppo."
L["Right you are, {name}. Stand steady now."] = "Senz'altro, {name}. Ora non muoverti."
L["Right away, {name}. Stay, now. I've always wanted to say that."] = "Subito, {name}. Resta! Ho sempre sognato di dirlo."
L["Gladly, {name}. Rain or shine, and in Gilneas it's rain."] = "Volentieri, {name}. Pioggia o sole, e a Gilneas è pioggia."
L["Certainly, {name}. I'll try not to shed on you."] = "Certo, {name}. Cercherò di non perdere pelo su di te."
L["Say no more, {name}. These ears heard you before you'd decided to ask."] = "Basta così, {name}. Le mie orecchie ti hanno sentito prima che tu chiedessi."
L["Of course, {name}. You asked nicer than the last fellow who threw me a stick."] = "Certo, {name}. Più gentile dell'ultimo tizio che mi ha tirato un legnetto."
L["Stay off the moors after dark, {name}. Take this."] = "Evita le brughiere dopo il tramonto, {name}. Prendi questo."
L["Keep your wits about you, {name}. Something is always hunting."] = "Tieni gli occhi aperti, {name}. C'è sempre qualcosa a caccia."
L["I'd have brought this sooner, {name}, but I stopped to chase something."] = "Te l'avrei portato prima, {name}, ma dovevo inseguire una cosa."
L["For you, {name}. No, I don't want a treat. Well. Perhaps a small one."] = "Per te, {name}. No, non voglio un biscottino. Be'. Magari uno piccolo."
L["Gilneans always offer, {name}. The claws are just part of the outfit."] = "Un gilneano offre sempre, {name}. Gli artigli sono solo un accessorio."
L["An old Gilnean remedy, {name}. Good for colds, gloom and most curses. Not mine."] = "Rimedio gilneano, {name}: per raffreddore, malumore e maledizioni. Non la mia."
L["Run with this, {name}. Trust me, I know about running."] = "Corri con questo, {name}. Fidati, di corse me ne intendo."
L["Fetched this for you, {name}. Don't make a thing of it."] = "Te l'ho riportato, {name}. Non farne un caso."
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "La maledizione ci lega, {name}, ma Gilneas ci lega ancora di più."
L["No need to explain the ears to you, {name}."] = "A te non devo spiegare le orecchie, {name}."
L["Fur, fog and rain, {name}. Only a Gilnean understands all three."] = "Pelo, nebbia e pioggia, {name}. Solo un gilneano capisce tutte e tre."
L["Pack looks after pack, {name}. Always has."] = "Il branco bada al branco, {name}. Da sempre."
L["Pack rules, {name}: nobody wanders off, and nobody mentions the fleas."] = "Regole del branco, {name}: nessuno si allontana, e nessuno parla delle pulci."
L["A pack again, {name}. I hadn't known how much I'd missed one."] = "Di nuovo un branco, {name}. Non sapevo quanto mi fosse mancato."
L["I'll catch the scent of trouble first, {name}. It's the one perk of the curse."] = "I guai li fiuto prima io, {name}. L'unico vantaggio della maledizione."
L["If I howl, {name}, it's a battle cry. Probably. Don't look at me like that."] = "Se ululo, {name}, è un grido di battaglia. Probabilmente. Non guardarmi così."
L["Lead on, {name}. I'll trot. It's undignified, but it's much quicker."] = "Fai strada, {name}. Io trotterello. Poco dignitoso, ma molto più veloce."
L["Night again, {name}. I'm at my best and my worst. This is the best part."] = "Di nuovo notte, {name}. Do il meglio e il peggio di me. Questo è il meglio."
L["Look at that moon, {name}. Don't mind me; I'm not howling. Much."] = "Guarda che luna, {name}. Non badare a me, non sto ululando. Non troppo."
L["Gilneas at night was fog and footsteps, {name}. These days I'm the footsteps."] = "Gilneas di notte era nebbia e passi, {name}. Ora i passi sono io."
L["Morning, {name}. I'd have been up sooner, but the rug by the fire was so warm."] = "Buongiorno, {name}. Il tappeto davanti al fuoco era troppo caldo per alzarsi."
L["Smells like rain this morning, {name}. Everything in Gilneas smelled like rain."] = "Stamattina c'è odore di pioggia, {name}. A Gilneas tutto sapeva di pioggia."
L["Up already, {name}? I've chased two rabbits. For exercise. Purely."] = "Già in piedi, {name}? Ho inseguito due conigli. Per allenamento. Giuro."
L["Throm-ka, {name}! Honour is repaid."] = "Throm-ka, {name}! L'onore è ripagato."
L["You give freely, {name}. I return the favour."] = "Tu doni senza chiedere, {name}. Io ricambio il favore."
L["Orcs keep their thanks short, {name}. Thanks."] = "Gli orchi ringraziano in breve, {name}. Grazie."
L["Orcs return every blow twice, {name}. The kind ones too."] = "Un orco rende ogni colpo due volte, {name}. Anche quelli gentili."
L["You helped me, I help you. Orc poetry, {name}. It doesn't rhyme."] = "Tu aiuti me, io aiuto te. Poesia orchesca, {name}. Fa rima per sbaglio."
L["In the old days I'd have repaid you with a boar, {name}. This keeps better."] = "Un tempo ti avrei ripagato con un cinghiale, {name}. Questo si conserva meglio."
L["Owing somebody itches worse than Durotar sand, {name}. There. Itch gone."] = "Un debito prude più della sabbia di Durotar, {name}. Ecco. Prurito passato."
L["Strong stuff, {name}. I could wrestle a kodo now. So can you."] = "Roba forte, {name}. Ora potrei fare a botte con un kodo. E anche tu."
L["Dabu, {name}. It is done."] = "Dabu, {name}. È fatto."
L["Hold still, {name}. Strength for the fight ahead."] = "Non muoverti, {name}. Forza per la battaglia che ti aspetta."
L["Ask an orc for help and you get it, {name}. Ask for subtlety and you wait."] = "Chiedi aiuto a un orco e lo ottieni, {name}. Chiedigli finezza e aspetti."
L["Help, yes. Hugging, no. Hold still, {name}."] = "Aiuto, sì. Abbracci, no. Non muoverti, {name}."
L["You want {buff}? You have {buff}, {name}. Next."] = "Vuoi {buff}? Hai {buff}, {name}. Avanti il prossimo."
L["Don't flinch, {name}. My helping face looks exactly like my fighting face."] = "Non tremare, {name}. La mia faccia da aiuto è identica a quella da battaglia."
L["Short question, short answer, {name}: yes."] = "Domanda breve, risposta breve, {name}: sì."
L["Lok'tar ogar, {name}! Take this into battle. A tavern brawl also counts."] = "Lok'tar ogar, {name}! Portalo in battaglia. Anche una rissa in taverna vale."
L["Blood and thunder, {name}! Go and earn your glory."] = "Sangue e tuono, {name}! Va' e conquista la tua gloria."
L["Among orcs, {name}, making you stronger is how we say we like you."] = "Tra orchi, {name}, renderti più forte è il nostro modo di dire che ci piaci."
L["An orc giving gifts unasked? Tell no one, {name}. It ruins the image."] = "Un orco che fa regali? Acqua in bocca, {name}. Rovina l'immagine."
L["I was told to be more diplomatic, {name}. This is me being diplomatic."] = "Mi hanno chiesto più diplomazia, {name}. Questa è la mia diplomazia."
L["Go hit something for me, {name}. Or set it on fire. Orcs aren't fussy."] = "Picchia qualcosa per me, {name}. O dagli fuoco. Gli orchi non fanno storie."
L["Don't thank me, {name}. Just win, and do it loudly."] = "Non ringraziarmi, {name}. Vinci, e fa' rumore."
L["I'd make a speech, {name}, but it's mostly shouting. Just take it."] = "Farei un discorso, {name}, ma sarebbe soprattutto urla. Prendi e basta."
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "Throm-ka, {name}! Il sangue dei clan scorre forte in te."
L["An orc, {name}! Finally, somebody who shouts at my volume."] = "Sangue orchesco, {name}! Finalmente qualcuno che urla al mio volume."
L["Frostwolf, Warsong or Blackrock, {name}, we all argue like family."] = "Lupi Bianchi, Cantaguerra o Roccianera, {name}: litighiamo come una famiglia."
L["Between orcs no words are needed, {name}. Good. I was out of them."] = "Tra orchi non servono parole, {name}. Meglio. Le avevo finite."
L["The plan, {name}: we hit it. Questions? No? Good plan."] = "Il piano, {name}: lo colpiamo. Domande? No? Ottimo piano."
L["A true warband, {name}. Loud, angry, and all on the same side for once."] = "Una vera schiera, {name}. Chiassosa, furiosa, e per una volta dalla stessa parte."
L["Stay with the warband, {name}. Strength in numbers. And in axes."] = "Resta con la schiera, {name}. L'unione fa la forza. E le asce pure."
L["If you fall, {name}, I carry you out. Complaining the whole way, but I carry."] = "Se cadi, {name}, ti porto fuori io. Lamentandomi tutto il tempo, ma ti porto."
L["Fight well, {name}, and tonight you share our fire. And our boasting."] = "Combatti bene, {name}, e stasera siedi al nostro fuoco. Spacconate incluse."
L["Thank you, {name}. It would warm my heart, if it still beat."] = "Grazie, {name}. Mi scalderebbe il cuore, se battesse ancora."
L["Such warmth, for one so cold? Returned in full, {name}."] = "Tanto calore per chi è così freddo? Te lo rendo tutto, {name}."
L["Thank you, {name}. I'd blush, but the blood stopped reaching my face."] = "Grazie, {name}. Arrossirei, ma il sangue non mi arriva più in faccia."
L["My undying gratitude, {name}. For once, the phrase is accurate."] = "Gratitudine eterna, {name}. Detto da un non-morto, è letterale."
L["Most kind, {name}. You've lifted me from 'deceased' to 'mildly deceased'."] = "Che gentilezza, {name}. Da trapassato remoto a trapassato prossimo."
L["You've added years to my life, {name}. Shame it already ended."] = "Mi hai allungato la vita di anni, {name}. Peccato sia già finita."
L["I felt that, {name}, and I don't feel much these days. Here, feel this."] = "L'ho sentito, {name}, e ormai sento ben poco. Tieni, senti questo."
L["I'd shake your hand, {name}, but I'm not sure mine is still attached."] = "Ti stringerei la mano, {name}, ma non so se la mia è ancora attaccata."
L["Certainly, {name}. Try not to die. It's overrated."] = "Certo, {name}. Cerca di non morire. È sopravvalutato."
L["You need only ask, {name}. The dead are patient."] = "Basta chiedere, {name}. I morti sono pazienti."
L["Ask the dead for a favour, {name}. We rarely have other plans."] = "Chiedi pure un favore ai morti, {name}. Raramente abbiamo altri impegni."
L["Certainly, {name}. Stand clear; I'd hate to drop anything on you."] = "Certo, {name}. Stai indietro: non vorrei perdere qualche pezzo su di te."
L["A moment, {name}. Rigor mortis is hard on the casting hand."] = "Un attimo, {name}. Il rigor mortis è duro con la mano che lancia."
L["Nice to be asked for something, {name}, besides the way to the graveyard."] = "Che bello, {name}, che mi si chieda qualcosa oltre alla strada per il cimitero."
L["Gladly, {name}. It takes my mind off the smell. Mine, I mean."] = "Volentieri, {name}. Mi distrae dall'odore. Il mio, intendo."
L["Stay among the living a little longer, {name}."] = "Resta tra i vivi ancora un po', {name}."
L["Take this, {name}. The grave can wait."] = "Prendi, {name}. La tomba può aspettare."
L["I was a physician in Lordaeron, {name}. Old habits die harder than I did."] = "Ero medico a Lordaeron, {name}. Certe abitudini sono più dure a morire di me."
L["No charge, {name}. The apothecaries would have made you sign something."] = "Gratis, {name}. Gli speziali ti avrebbero fatto firmare qualcosa."
L["A gift from the grave, {name}. Don't worry, I washed it."] = "Un dono dalla tomba, {name}. Niente paura, l'ho lavato."
L["Every body needs a little help, {name}. Mine mostly needs stitches."] = "Tutti hanno bisogno di una mano, {name}. Io ne perdo una a settimana."
L["I've seen where heroes end up, {name}. I live there. Take this."] = "Ho visto dove finiscono gli eroi, {name}. Ci abito. Prendi."
L["Take this, {name}. I learned the hard way you can't take it with you."] = "Prendi, {name}. Ho imparato a mie spese che nella tomba non te lo porti."
L["We Forsaken must look after each other, {name}."] = "Noi Reietti dobbiamo badare l'uno all'altro, {name}."
L["Between us corpses, {name}, you're remarkably well preserved."] = "Detto tra cadaveri, {name}, ti conservi benissimo."
L["Lose a finger, {name}, and I've a spare. Forsaken share."] = "Perdi un dito, {name}? Te ne presto uno. Tra Reietti si usa."
L["Is your jaw clicking too, {name}, or is that just me?"] = "Anche a te scricchiola la mascella, {name}, o è solo la mia?"
L["Stay alive, {name}. I've tried the alternative, and I can't recommend it."] = "Resta in vita, {name}. Ho provato l'alternativa e non la consiglio."
L["If I fall down, {name}, give it a minute. Old habit."] = "Se cado, {name}, dammi un minuto. Vecchia abitudine."
L["I'll take the front, {name}. What's the worst that could happen? Again?"] = "Sto davanti io, {name}. Cosa potrebbe succedere di peggio? Di nuovo?"
L["Keep upwind of me, {name}. It's better for morale."] = "Stammi sopravento, {name}. È meglio per il morale."
L["The last party I joined, {name}, I woke up in a crypt. Let's improve on that."] = "Col mio ultimo gruppo, {name}, il risveglio fu in una cripta. Facciamo meglio."
L["The dead keep terrible hours, {name}. Nice to have company for once."] = "I morti fanno orari assurdi, {name}. Bello avere compagnia, per una volta."
L["Midnight, {name}: the best hour to be up and about when you shouldn't be."] = "Mezzanotte, {name}: l'ora migliore per andare in giro quando non si dovrebbe."
L["The living are all asleep, {name}. We Forsaken call this the quiet shift."] = "I vivi dormono, {name}. Noi Reietti lo chiamiamo il turno tranquillo."
L["Morning already, {name}? I've been up all night. And all of last decade."] = "Già mattina, {name}? Sono in piedi da ieri sera. E dallo scorso decennio."
L["The sun's up, {name}. I'll stand in the shade, if you don't mind. Things peel."] = "C'è il sole, {name}. Io sto all'ombra, se permetti: qui si spella tutto."
L["Early start, {name}. The dead never sleep in. Or at all, really."] = "Di buon'ora, {name}. I morti non poltriscono. Anzi, non dormono proprio."
L["The Earth Mother saw your kindness, {name}. She nudged me. Quite hard."] = "La Madre Terra ha notato il tuo gesto, {name}. E mi ha dato di gomito. Forte."
L["Thank you, {name}. May the winds guide you."] = "Grazie, {name}. Che i venti ti guidino."
L["Thank you, {name}. I'm deeply moved, and it takes a lot to move a tauren."] = "Grazie, {name}. Mi hai commosso, e smuovere un tauren non è facile."
L["It's a long way up to a tauren's heart, {name}. You found it."] = "Il cuore di un tauren sta in alto, {name}. L'hai raggiunto."
L["I felt that from horn to hoof, {name}. Returned, hoof to horn."] = "L'ho sentito dalle corna agli zoccoli, {name}. E ritorno."
L["A gift given is a seed planted, {name}. Here is the harvest."] = "Un dono fatto è un seme piantato, {name}. Ecco il raccolto."
L["That deserves a feast, {name}. The feast can wait; {buff} can't."] = "Questo merita un banchetto, {name}. Il banchetto può aspettare; {buff} no."
L["Thank you, {name}. Should you ever need a wall to hide behind, I'm free."] = "Grazie, {name}. Se ti serve un muro dietro cui nasconderti, sono a disposizione."
L["Of course, {name}. Stand tall and be at peace. I'll handle the tall part."] = "Certo, {name}. Testa alta e resta in pace. Alla parte 'alta' ci penso io."
L["Ask and it is given, {name}. The herd shares what it has."] = "Chiedi e ti sarà dato, {name}. La mandria divide ciò che ha."
L["Of course, {name}. Stand back a pace; I do this with my whole body."] = "Certo, {name}. Fai un passo indietro: lo faccio con tutto il corpo."
L["Gladly, {name}. Mind the tail."] = "Con piacere, {name}. Occhio alla coda."
L["The Earth Mother gives freely, {name}, and so do her largest children."] = "La Madre Terra dona senza riserve, {name}, e così i suoi figli più grossi."
L["Gladly, {name}. Tauren are slow to anger and quick to help. Quick-ish."] = "Volentieri, {name}. Noi tauren: lenti all'ira, svelti ad aiutare. Si fa per dire."
L["Refuse you, {name}? My ancestors would never let me hear the end of it."] = "Dirti di no, {name}? I miei antenati me lo rinfaccerebbero per l'eternità."
L["Walk with the Earth Mother, {name}. She's everywhere, so you can't get lost."] = "Cammina con la Madre Terra, {name}. È ovunque, quindi non puoi perderti."
L["May An'she light your path, {name}."] = "Che An'she illumini il tuo cammino, {name}."
L["You looked like you could use a friend, {name}. I'm a very big one."] = "Ti serviva una spalla, {name}? Ne ho due, belle grosse."
L["Take this, {name}. The Earth Mother would scold me if I walked past."] = "Prendi, {name}. La Madre Terra mi sgriderebbe se tirassi dritto."
L["Tread lightly, {name}. Take it from someone who never has."] = "Passo leggero, {name}. Fidati di chi non ce l'ha mai avuto."
L["The wind said you'd pass this way, {name}. The wind is a terrible gossip."] = "Il vento ti ha annunciato, {name}. Il vento è un gran pettegolo."
L["Take this, {name}. I'd lend you my kodo too, but he's less generous than me."] = "Prendi, {name}. Ti presterei anche il mio kodo, ma è meno generoso di me."
L["The shu'halo say carry what you can for others, {name}. I can carry a lot."] = "Gli shu'halo dicono: porta ciò che puoi per gli altri, {name}. Io posso molto."
L["The Earth Mother watches over us both, {name}."] = "La Madre Terra veglia su di noi due, {name}."
L["Somebody warn the doorframes, {name}. There are two of us now."] = "Qualcuno avverta gli stipiti, {name}. Adesso siamo in due."
L["Plains or peaks, {name}, a shu'halo heart is a big one."] = "Pianure o vette, {name}, il cuore di uno shu'halo è grande."
L["Horns and helmets, {name}. Only another tauren knows the pain."] = "Un elmo coi buchi giusti, {name}: solo un tauren sa che strazio trovarlo."
L["Get behind me, {name}. There's room back there for the whole party."] = "Mettiti dietro di me, {name}. C'è posto per tutto il gruppo."
L["The herd moves together, {name}. Mind my hooves; the herd has learned to."] = "La mandria si muove unita, {name}. Occhio ai miei zoccoli: la mandria ha imparato."
L["Low ceilings ahead, {name}? I'll be the first to find out. Take this."] = "Soffitti bassi più avanti, {name}? La mia testa lo scoprirà per prima. Prendi."
L["I'm slow to anger, {name}, but I hold a grudge for the whole party."] = "Mi arrabbio piano, {name}, ma porto rancore per tutto il gruppo."
L["Need a wall to hide behind, {name}? I'm most of one. Come on."] = "Ti serve un muro, {name}? Io lo sono quasi. Vieni."
L["An'she rises, {name}, and so do we. Slower, in my case."] = "An'she sorge, {name}, e noi con lui. Io un po' più lentamente."
L["The sun is An'she's eye, {name}. He's watching, so let's look busy."] = "Il sole è l'occhio di An'she, {name}. Ci guarda: facciamo finta di lavorare."
L["Morning, {name}. The kodo are up, the grass is wet, and this is yours."] = "Buongiorno, {name}. I kodo sono svegli, l'erba è bagnata, e questo è tuo."
L["Mu'sha keeps the night watch, {name}. I'll tell her to keep an eye on you."] = "Mu'sha fa la guardia di notte, {name}. Le dirò di tenerti d'occhio."
L["The moon's out, {name}. Mu'sha sees you, and she approves. I asked."] = "C'è la luna, {name}. Mu'sha ti vede, e approva. Gliel'ho chiesto."
L["Late, {name}. The kodo are asleep, and they snore like thunder. Take this."] = "È tardi, {name}. I kodo dormono, e russano come tuoni. Prendi."
L["Ya be too kind, {name}! Dis one be from me."] = "Si' troppo gentile, {name}! Chisto t'o dong' io."
L["Thanks, mon! Da spirits smile on ya, {name}."] = "Grazie assaje, cumpà! 'E spiriti te sorrideno, {name}."
L["Ya gave me good mojo, {name}. Now ya get some back, extra spicy."] = "M'hai dato buon mojo, {name}. Mo' te lo torno, cu 'o peperoncino."
L["Bwonsamdi gonna be real disappointed, {name}. Thanks, mon."] = "Bwonsamdi ce resta malissimo, {name}. Grazie, cumpà."
L["Dat be some fine work, {name}. Almost as fine as me. Almost."] = "Bello lavoro, {name}. Bello quasi quanto a me. Quasi."
L["A troll can grow back a hand, {name}. Can't grow back honour. Here."] = "A 'nu troll 'na mano ricresce, {name}. L'onore no. Piglia."
L["Ya just made a troll smile, {name}, and we got a lot of teeth."] = "Hai fatto ridere 'nu troll, {name}. E tenimmo assaje diente."
L["Da loa keep a tally, {name}, and now ya on da good side of it."] = "'E loa tengono 'o conto, {name}, e mo' stai dalla parte bbona."
L["Sure ting, {name}. Hold still; da mojo don't like a movin' target."] = "Sicuro, {name}. Nun te movere: 'o mojo nun ama 'e bersagli mobili."
L["No worries, {name}. Da loa got ya covered."] = "Nun te preoccupà, {name}. Ce pensano 'e loa."
L["Stay away from da voodoo, {name}. ...Except dis voodoo. Dis one fine."] = "Statte luntano d''o voodoo, {name}. ...Tranne chisto. Chisto va bbuono."
L["Close ya eyes, {name}. Da mojo be shy when people watch."] = "Chiudi l'uocchie, {name}. 'O mojo è timido si 'a gente guarda."
L["Ya don't gotta ask twice, {name}. Ya barely gotta ask once."] = "Nun c'è bisogno 'e chiedere due volte, {name}. Manco una."
L["Sure, {name}. Bein' a troll be mostly swagger. Da rest be dis."] = "Certo, {name}. 'Nu troll è quasi tutto stile. 'O resto è chisto."
L["Ya asked real polite, {name}. Polite get da good stuff."] = "Hai chiesto con garbo, {name}. A chi è educato, 'a roba bbona."
L["Da loa be watchin' over ya, {name}. Dey real nosy like dat."] = "'E loa te guardano 'e spalle, {name}. So' curiosi assaje."
L["Stay sharp out dere, {name}. Take dis wit' ya."] = "Occhi aperti llà fore, {name}. Pigliate chisto."
L["Ya look like somebody who appreciate quality, {name}. Here: quality."] = "Tieni 'a faccia 'e chi apprezza 'a qualità, {name}. Ecco: qualità."
L["Take dis, {name}. Walk like ya own da jungle. I do."] = "Piglia, {name}. Cammina da padrone d''a giungla. Comme a me."
L["Everybody need mojo, {name}. I make so much I gotta give it away."] = "A tutti serve 'o mojo, {name}. Io ne tengo accussì tanto che 'o regalo."
L["A little somethin' for ya, {name}. Don't ask where da loa got it."] = "'Nu pensierino pe' te, {name}. Nun chiedere addò l'hanno pigliato 'e loa."
L["Go on, {name}. Anyting try to eat ya now gonna get indigestion."] = "Vai, {name}. Mo' chi te magna se piglia 'n'indigestione."
L["Ya lookin' dangerous now, {name}. Almost troll-level dangerous."] = "Mo' tieni 'n'aria pericolosa, {name}. Quasi comme 'nu troll."
L["Hey, {name}! Always good to see family, mon."] = "Uè, {name}! Fa sempre piacere vedé 'a famiglia, cumpà."
L["Da rest of Azeroth stand up straight, {name}. We got more style."] = "'O resto 'e Azeroth sta dritto, {name}. Nuje tenimmo cchiù stile."
L["Hey, {name}, ya tusks be lookin' sharp. Mine too, obviously."] = "Uè, {name}, che zanne eleganti. Pure 'e mie, se capisce."
L["Every troll be family, {name}. Even da ones who still owe me gold."] = "Ogni troll è famiglia, {name}. Pure chi me deve ancora 'e sorde."
L["Stay close, {name}. Trolls regenerate; da rest of ya gotta be careful."] = "Stamme vicino, {name}. 'E troll se rigenerano; vuje no, quindi occhio."
L["Dis crew got style, {name}. Now it got mojo too."] = "Sta compagnia tene stile, {name}. Mo' tene pure 'o mojo."
L["We go in together, {name}, we come out together. Dat be da whole plan, mon."] = "Trasimmo insieme, {name}, e ascimmo insieme. Chisto è tutto 'o piano, cumpà."
L["Nobody fallin' today, {name}. Bwonsamdi can wait for da next group."] = "Oggi nun cade nisciuno, {name}. Bwonsamdi aspettasse 'o prossimo gruppo."
L["Keep ya head down, {name}. I keep mine up. Somebody gotta look good."] = "Tieni 'a capa bassa, {name}. Io 'a tengo auta: qualcuno adda fa' bella figura."
L["Night be da best time for mojo, {name}. Nobody see where it come from."] = "'A notte è l'ora d''o mojo, {name}. Nisciuno vede da dove vene."
L["Da jungle wake up at night, {name}. So do I. Here, dis one fresh."] = "'A giungla se sceta 'e notte, {name}. Pure io. Piglia, chisto è frisco."
L["Moon be high, {name}, spirits be restless. Dis keep dem off ya."] = "Luna auta, {name}, spiriti irrequieti. Chisto t''e tene luntano."
L["Such courtesy does you credit, {name}. Nearly as much as it does me."] = "Tanta cortesia ti fa onore, {name}. Quasi quanto ne fa a me."
L["How gracious, {name}. Allow me to return the favour."] = "Che gesto raffinato, {name}. Permettimi di ricambiare il favore."
L["Thank you, {name}. I haven't felt this radiant since... well, this morning."] = "Grazie, {name}. Non mi sentivo così raggiante da... be', stamattina."
L["Kind of you, {name}. We sin'dorei never turn down free magic. Ask anyone."] = "Che gentile, {name}. Un sin'dorei non rifiuta mai magia gratis. Chiedi in giro."
L["Exquisite, {name}. I would know; I only accept the exquisite."] = "Squisito, {name}. Me ne intendo: accetto solo ciò che è squisito."
L["Lovely, {name}. I'll be insufferable about this all day. More than usual."] = "Delizioso, {name}. Sarò insopportabile tutto il giorno. Più del solito."
L["Thank you, {name}. It even goes with my gold trim. You have an eye."] = "Grazie, {name}. Si abbina persino alle mie finiture dorate. Hai occhio."
L["Returned in kind, {name}. A prettier kind, admittedly. I can't help it."] = "Ricambiato, {name}. In modo più grazioso, lo ammetto. Non posso farci niente."
L["Naturally, {name}. Only the finest for you."] = "Naturalmente, {name}. Solo il meglio per te."
L["For you, {name}? Of course. The sun gives freely."] = "Per te, {name}? Ma certo. Il sole dona senza riserve."
L["Patience, {name}. Radiance can't be rushed, only admired."] = "Pazienza, {name}. Lo splendore non si mette fretta: si ammira."
L["Of course, {name}. {buff}, delivered with impeccable posture."] = "Certo, {name}. {buff}, con un portamento impeccabile."
L["You asked nicely, {name}. In Silvermoon that counts for everything."] = "Hai chiesto con garbo, {name}. A Lunargenta è tutto ciò che conta."
L["One moment, {name}. I never cast anything without checking my hair."] = "Un momento, {name}. Non lancio mai nulla senza sistemarmi i capelli."
L["At once, {name}. Keeping someone waiting is so terribly unfashionable."] = "Subito, {name}. Far aspettare qualcuno è così terribilmente fuori moda."
L["Anar'alah belore, {name}. May the sun guide you, and light your good side."] = "Anar'alah belore, {name}. Che il sole ti guidi, e illumini il tuo lato migliore."
L["Shorel'aran, {name}. Fight with elegance."] = "Shorel'aran, {name}. Combatti con eleganza."
L["Take this, {name}. Whatever happens out there is merely a setback."] = "Prendi, {name}. Qualunque cosa succeda là fuori, sarà solo un contrattempo."
L["Everyone deserves to shine, {name}. Only a little less than me, of course."] = "Tutti meritano di brillare, {name}. Un po' meno di me, s'intende."
L["The sun is with you, {name}. I simply held the door for it."] = "Il sole è con te, {name}. Io gli ho solo tenuto la porta."
L["Go on, {name}, take it. The Sunwell's back; we can afford to be generous."] = "Prendi pure, {name}. Il Pozzo Solare è tornato: ce lo possiamo permettere."
L["For you, {name}: {buff}, lightly scented with Silvermoon."] = "Per te, {name}: {buff}, con un leggero profumo di Lunargenta."
L["Here, {name}. Hand-cast in Silvermoon, so do try not to scuff it."] = "Tieni, {name}. Artigianato di Lunargenta: cerca di non graffiarlo."
L["The Sunwell shines for us both, {name}."] = "Il Pozzo Solare splende per noi due, {name}."
L["Two sin'dorei in one place, {name}. The day just got twice as elegant."] = "Due sin'dorei insieme, {name}. Eleganza raddoppiata."
L["You too, {name}? Two sin'dorei, one mirror. We'll have to take turns."] = "Anche tu, {name}? Due sin'dorei, uno specchio. Dovremo fare a turno."
L["Like the phoenix, {name}: we keep rising, and we look good doing it."] = "Come la fenice, {name}: risorgiamo sempre, e con stile."
L["Do keep pace, {name}. We have a reputation for arriving beautifully."] = "Tieni il passo, {name}. Abbiamo una reputazione: arrivare con eleganza."
L["Stand where the light is good, {name}. If we must fight, we'll look splendid."] = "Mettiti in buona luce, {name}. Se si deve combattere, tanto vale essere splendidi."
L["A party at last, {name}. I did dress for one."] = "Un gruppo, finalmente, {name}. E ho l'abito da festa."
L["The sun shines on all of us, {name}. Mostly on me, but it shares."] = "Il sole splende su tutti noi, {name}. Soprattutto su di me, ma condivide."
L["One for you, {name}, and one for the party's image, which I've taken on myself."] = "Uno per te, {name}, e uno per l'immagine del gruppo, di cui mi occupo io."
L["The sun has risen, {name}, and so have I. We coordinate."] = "Il sole è sorto, {name}, e io con lui. Ci coordiniamo."
L["Dawn over Quel'Thalas is lovelier, {name}, but this will do. Just."] = "L'alba su Quel'Thalas è più bella, {name}, ma questa può andare. A malapena."
L["Morning light, {name}. The most flattering hour. For both of us, naturally."] = "Luce del mattino, {name}: l'ora che dona di più. A te e a me, naturalmente."
L["Your generosity is noted, {name}. In triplicate. Suramar remembers its friends."] = "Generosità annotata, {name}. In triplice copia. Suramar ricorda i suoi amici."
L["Most gracious, {name}. Allow me to repay you in kind."] = "Assai cortese, {name}. Permettimi di ricambiare come si conviene."
L["Thank you, {name}. Ten thousand years under a dome; I'm still practising that."] = "Grazie, {name}. Diecimila anni sotto una cupola: ci sto ancora prendendo la mano."
L["A gift with no favour owed? The court would faint. Thank you, {name}."] = "Un dono senza favori in cambio? A corte sverrebbero. Grazie, {name}."
L["Returned, {name}. We keep careful accounts of kindness. And of slights."] = "Ricambiato, {name}. Teniamo un conto preciso delle gentilezze. E degli sgarbi."
L["I'll mention you to First Arcanist Thalyssra, {name}. Favourably, even."] = "Parlerò di te alla Prima Arcanista Thalyssra, {name}. Persino bene."
L["Most kind, {name}. In Suramar we'd hold a banquet. Consider it held."] = "Molto gentile, {name}. A Suramar daremmo un banchetto. Consideralo dato."
L["I'd send a formal letter of thanks, {name}, but this seemed quicker."] = "Una lettera formale di ringraziamento, {name}? Così si fa prima."
L["Of course, {name}. A little arcane polish, just for you."] = "Certo, {name}. Un po' di lustro arcano, solo per te."
L["A reasonable request, {name}. Granted."] = "Una richiesta ragionevole, {name}. Concessa."
L["Certainly, {name}. The short version; the long one takes a lunar cycle."] = "Certamente, {name}. La versione breve: quella lunga richiede un ciclo lunare."
L["A request, how refreshing. The court only ever made demands. Here, {name}."] = "Una richiesta, che novità. A corte si pretendeva e basta. Ecco, {name}."
L["Done, {name}, and free. Elisande would have charged you a favour for it."] = "Fatto, {name}, e gratis. Elisande ti avrebbe chiesto un favore in cambio."
L["There, {name}. No need to bow. A small nod would be lovely, though."] = "Ecco, {name}. Non serve inchinarsi. Un cenno del capo, però, sarebbe gradito."
L["Of course, {name}. I've perfected this since before most cities had walls."] = "Certo, {name}. Lo perfeziono da prima che quasi tutte le città avessero mura."
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "Prendi, {name}. I doni arcani sono sprecati per chi sta in ozio."
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "Una scintilla dell'arcano di Suramar, {name}. Usala con saggezza."
L["I've gone without magic once, {name}. I don't recommend it. Take this."] = "Ho già fatto a meno della magia, {name}. Non lo consiglio. Prendi."
L["The world outside the dome is so large, {name}. And so under-enchanted. Here."] = "Il mondo fuori dalla cupola è così grande, {name}. E così poco incantato. Tieni."
L["Arcwine is traditional, {name}, but {buff} travels better."] = "Il vino arcano è tradizione, {name}, ma {buff} viaggia meglio."
L["Do take this, {name}. It's rude to refuse Suramar's hospitality. Very rude."] = "Prendi pure, {name}. È scortese rifiutare l'ospitalità di Suramar. Molto scortese."
L["Here, {name}. I'm told this is how outsiders say hello. Charming custom."] = "Tieni, {name}. Mi dicono che fuori si saluta così. Usanza deliziosa."
L["Take this, {name}. Magic hoarded is magic spoiled, as Suramar learned."] = "Prendi, {name}. Magia accumulata è magia sprecata: Suramar l'ha imparato."
L["Suramar's children shine together again, {name}."] = "I figli di Suramar tornano a brillare insieme, {name}."
L["Shal'dorei, {name}! You packed arcwine? Outsider wine is just... grapes."] = "Shal'dorei, {name}! Hai portato il vino arcano? Il vino di fuori è solo... uva."
L["Suramar's own, {name}. Try not to be too impressed by the rest of the world."] = "Siamo di Suramar, {name}. Non lasciarti impressionare troppo dal resto del mondo."
L["We survived the Legion and the withering, {name}. The rest is small talk."] = "Legione e avvizzimento superati, {name}. Il resto sono chiacchiere."
L["An expedition, {name}! In Suramar this needed six permits and a masquerade."] = "Una spedizione, {name}! A Suramar servivano sei permessi e un ballo in maschera."
L["The dome kept us safe, {name}. Now we must make do with one another. Gladly."] = "La cupola ci proteggeva, {name}. Ora dobbiamo arrangiarci tra noi. Con piacere."
L["Arcane for everyone, {name}. The court would call it waste. I call it company."] = "Arcano per tutti, {name}. A corte lo chiamerebbero spreco. Io lo chiamo compagnia."
L["Do follow my lead, {name}. I've had ten thousand years of walking in step."] = "Seguimi pure, {name}. Ho diecimila anni di passo cadenzato alle spalle."
L["In a party one shares one's magic, {name}. How novel. I rather like it."] = "In gruppo si condivide la magia, {name}. Che novità. Mi piace, direi."
L["Night at last, {name}. Add a few thousand lanterns and it's nearly Suramar."] = "Finalmente notte, {name}. Aggiungi qualche migliaio di lanterne ed è quasi Suramar."
L["Under the dome it was always night, {name}. I feel quite at home."] = "Sotto la cupola era sempre notte, {name}. Mi sento proprio a casa."
L["The stars are out, {name}. We had better ones in Suramar. These will do."] = "Sono uscite le stelle, {name}. A Suramar erano più belle. Queste possono andare."
L["Daylight, {name}. Ten thousand years under a dome, and it still startles me."] = "La luce del giorno, {name}. Diecimila anni sotto una cupola, e ancora mi sorprende."
L["An early hour, {name}. The court never rose before noon. I'm reforming."] = "Di buon'ora, {name}. A corte ci si alzava a mezzogiorno. Sto cambiando."
L["Morning, {name}. The sun here is so very... unenchanted. Take this instead."] = "Buongiorno, {name}. Il sole qui è così... disincantato. Prendi questo, piuttosto."
L["A favour for a favour, {name}! Pleasure doing business."] = "Favore per favore, {name}! È un piacere fare affari con te."
L["Thanks, {name}! Consider your account settled in full."] = "Grazie, {name}! Il tuo conto è saldato per intero."
L["Aw, {name}. I'd invoice you, but I'm feeling sentimental. It'll pass."] = "Oh, {name}. Ti farei la fattura, ma oggi sono sentimentale. Passerà."
L["Thanks, {name}! I checked it for fine print. There wasn't any. Weird!"] = "Grazie, {name}! Ho cercato le clausole in piccolo. Niente. Strano!"
L["Returned with interest, {name}. Minus the interest. Don't get used to it."] = "Ricambiato con gli interessi, {name}. Interessi esclusi. Non ci fare l'abitudine."
L["Much obliged, {name}! You've just been upgraded to preferred customer."] = "Grazie mille, {name}! Da oggi hai la tessera cliente oro."
L["I'd name a rocket after you, {name}, but my rockets never last long. Thanks!"] = "Ti dedicherei un razzo, {name}, ma i miei razzi non durano mai molto. Grazie!"
L["I'd have charged fifty gold for that, {name}. Let's call us even."] = "Io l'avrei fatto pagare cinquanta d'oro, {name}. Facciamo pari."
L["You got it, {name}! Time is money, friend!"] = "Detto fatto, {name}! Il tempo è denaro, amico!"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "Affare fatto, {name}! Lo metto sul tuo conto. Scherzo!"
L["Right away, {name}! Satisfaction guaranteed or your {buff} back."] = "Subito, {name}! {buff}: soddisfatti o rimborsati."
L["{buff}, {name}! Tips optional. Encouraged. Optional."] = "{buff}, {name}! Mancia facoltativa. Gradita. Facoltativa."
L["Fast, cheap or good, {name}? Today you get all three. Don't spread it around."] = "Veloce, economico o fatto bene, {name}? Oggi tutti e tre. Non spargere la voce."
L["Sure thing, {name}! No explosions this time, I promise. Mostly promise."] = "Certo, {name}! Niente esplosioni stavolta, promesso. Quasi promesso."
L["For you, {name}? No charge. Put that in writing and I'll deny it."] = "Per te, {name}? Gratis. Mettilo per iscritto e negherò tutto."
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "Questo lo offre la casa, {name}. Non dirlo al Principe del Commercio."
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "Roba di prima scelta, zero commissioni, {name}. Solo per oggi!"
L["Free sample, {name}! If you like it, you know where to find me."] = "Campione omaggio, {name}! Se ti piace, sai dove trovarmi."
L["Here, {name}. If anything explodes near you today, that was unrelated."] = "Tieni, {name}. Se oggi ti esplode qualcosa vicino, io non c'entro."
L["Goodwill's an asset, {name}. Here's some {buff} for my books."] = "Anche la simpatia va a bilancio, {name}. Ecco {buff}."
L["Take this, {name}. Safety first! Or third. It's on the list somewhere."] = "Prendi, {name}. Prima la sicurezza! O terza. È in lista, da qualche parte."
L["Cast in record time, {name}! The record's mine. I set it just now."] = "Lanciato a tempo di record, {name}! Il record è mio. L'ho appena stabilito."
L["Kaja'Cola gives you ideas, {name}. This does the rest. Take it!"] = "Kaja'Cola ti dà le idee, {name}. Questo fa il resto. Prendi!"
L["Anything for a fellow entrepreneur, {name}!"] = "Tutto per un collega imprenditore, {name}!"
L["Kezan's finest, together again, {name}. Keep a hand on your coin purse."] = "Il meglio di Kezan, di nuovo insieme, {name}. Tieni una mano sul borsello."
L["Fellow goblin, {name}? Then you know this is a very, very rare discount."] = "Anche tu goblin, {name}? Allora sai che questo è uno sconto rarissimo."
L["Goblins look after goblins, {name}. It's cheaper than hiring guards."] = "I goblin badano ai goblin, {name}. Costa meno che assumere guardie."
L["Group rate, {name}! Everybody here gets it half off. Of free."] = "Tariffa di gruppo, {name}! Tutti a metà prezzo. Metà di gratis."
L["Nobody dies on my contract, {name}. The paperwork's a nightmare."] = "Col mio contratto non muore nessuno, {name}. Troppe scartoffie."
L["We split the loot even, {name}. I'll do the maths. Trust me."] = "Bottino in parti uguali, {name}. I conti li faccio io. Fidati."
L["Team-building, {name}! You make everybody stronger, and they all owe you."] = "Team building, {name}! Rendi tutti più forti, e tutti ti devono qualcosa."
L["Stick together, {name}. Mercenaries cost gold; friends only cost this."] = "Restiamo uniti, {name}. I mercenari costano oro; gli amici solo questo."
L["Early bird gets the gold, {name}! Here's a freebie. Don't tell the other birds."] = "Il mattino ha l'oro in bocca, {name}! Un omaggio. Non dirlo a chi dorme."
L["Morning, {name}! Markets open in an hour. Until then, I'm feeling generous."] = "Buongiorno, {name}! I mercati aprono tra un'ora. Fino ad allora, offro io."
L["Up early, {name}? Smart. Time is money, and it's cheapest in the morning."] = "Già in piedi, {name}? Mossa furba. Il tempo è denaro, e al mattino costa meno."
L["Thank you, {name}! The caravan always repays a kindness. Usually in string."] = "Grazie, {name}! La carovana ricambia sempre una gentilezza. Di solito in spago."
L["How kind, {name}! You're on the caravan's good list now."] = "Che gentile, {name}! Ora sei nella lista dei buoni della carovana."
L["Oh, I'll keep this, {name}! I keep everything. Here's one for you."] = "Oh, questo me lo tengo, {name}! Io tengo tutto. Eccone uno per te."
L["Thanks, {name}! Here's yours back. Well, a new one. Hardly used."] = "Grazie, {name}! Te lo rendo. Be', uno nuovo. Usato pochissimo."
L["My ears just went straight up, {name}. That means I'm very pleased."] = "Mi si sono drizzate le orecchie, {name}. Vuol dire che sono al settimo cielo."
L["By tonight's campfire, {name}, this story will have a sandworm in it. Thanks!"] = "Al falò di stasera, {name}, questa storia avrà un verme delle sabbie. Grazie!"
L["I'd gift-wrap yours, {name}, but all my wrapping is somebody's old map."] = "Te lo incarterei, {name}, ma la mia carta regalo è la vecchia mappa di qualcuno."
L["The alpacas saw that, {name}. They'll tell everyone how nice you are. Thanks!"] = "Gli alpaca hanno visto, {name}. Diranno a tutti quanto sei gentile. Grazie!"
L["Of course, {name}! Shake the sand out and hold still."] = "Certo, {name}! Scuoti via la sabbia e non muoverti."
L["Coming right up, {name}! Caravan service, no waiting."] = "Arriva subito, {name}! Servizio carovana, niente attese."
L["Sure, {name}! Let me dig it out... rope, rocks, a nice rock... here it is!"] = "Certo, {name}! Fammi cercare... corda, sassi, un bel sasso... eccolo!"
L["Hold on, {name}! Tail's in the way, one moment... there!"] = "Aspetta, {name}! La coda è d'intralcio, un attimo... ecco!"
L["One {buff}, {name}! Only slightly sandy."] = "{buff} per te, {name}! Con appena un po' di sabbia."
L["Ask a vulpera and you'll get something, {name}. Usually odd. Not today!"] = "Chiedi a un vulpera e ricevi qualcosa, {name}. Di solito strano. Oggi no!"
L["Yours, {name}! Vulpera love giving things. Almost as much as finding them."] = "Tuo, {name}! Ai vulpera piace regalare. Quasi quanto trovare."
L["Every traveller needs something for the road, {name}. I checked: not a rock."] = "Ogni viandante merita qualcosa per il viaggio, {name}. Controllato: niente sassi."
L["Keep this, {name}. The desert is long and the water is short."] = "Tienilo, {name}. Il deserto è lungo e l'acqua è poca."
L["Found this lying around, {name}. Kidding! It's fresh. Take it!"] = "L'ho trovato per terra, {name}. Scherzo! È fresco. Prendi!"
L["Here, {name}. Best thing in my pack, and I've got a lot of pack."] = "Tieni, {name}. La cosa migliore nel mio zaino, e di zaino ne ho parecchio."
L["In the dunes you share your shade and your spells, {name}. Here."] = "Tra le dune si condividono l'ombra e gli incantesimi, {name}. Tieni."
L["Some {buff} for you, {name}. I'd haggle, but you look busy."] = "Un po' di {buff} per te, {name}. Contratterei, ma hai da fare."
L["A gift from the whole caravan, {name}! They'll never know."] = "Un regalo da tutta la carovana, {name}! Non lo sapranno mai."
L["For the road, {name}. Roads are the best part. Roads, and snacks."] = "Per la strada, {name}. La strada è il bello. La strada, e gli spuntini."
L["A fellow wanderer! The caravan is never far, {name}."] = "Un compagno di strada! La carovana non è mai lontana, {name}."
L["Ears up, {name}! Always nice to share a spell with a fellow fox."] = "Orecchie dritte, {name}! Un incantesimo tra volpi è sempre un piacere."
L["One vulpera to another, {name}: I've three spare spoons if you need one."] = "Da vulpera a vulpera, {name}: ho tre cucchiai di scorta, se ti serve."
L["Vol'dun raised us both, {name}. Sand in the fur, luck in the pack."] = "Siamo figli di Vol'dun, {name}. Sabbia nel pelo, fortuna nello zaino."
L["Caravan rules, {name}: stay together, share the water, nobody sells the alpaca."] = "Regole della carovana, {name}: uniti, acqua per tutti, e l'alpaca non si vende."
L["Anything shiny in there, {name}, I saw it first. Caravan law."] = "Se luccica, {name}, l'ho visto prima io. Legge della carovana."
L["One for the party, {name}! A caravan's only as fast as its slowest alpaca."] = "Uno per il gruppo, {name}! Una carovana va veloce quanto il suo alpaca più lento."
L["Keep your pack shut, {name}. I don't mean to take things. They follow me."] = "Chiudi lo zaino, {name}. Non prendo le cose apposta: sono loro che mi seguono."
L["Lost in a city, {name}, never in a cave. Caves are just houses with no rent."] = "In città mi perdo, {name}, in grotta mai. Le grotte sono case senza affitto."
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids."] = "Noi vulpera viaggiamo di notte, {name}. Sabbia fresca, scorpidi assonnati."
L["Desert nights get cold, {name}. Here, something warm-ish."] = "Di notte il deserto gela, {name}. Ecco qualcosa di tiepidino."
L["Stars out, {name}. Every one's a signpost if you know how to read it. I don't."] = "Ecco le stelle, {name}. Ognuna è un cartello, se sai leggerla. Io no."
L["A kindness returned is a kindness doubled, {name}."] = "Una gentilezza ricambiata è una gentilezza raddoppiata, {name}."
L["Thank you, {name}. You have restored my balance."] = "Grazie, {name}. Hai ristabilito il mio equilibrio."
L["Somewhere, a Sha just went hungry. Thank you, {name}."] = "Da qualche parte, uno Sha è rimasto a digiuno. Grazie, {name}."
L["Thank you, {name}. Aysa would bow, Ji would cheer. I will do both, badly."] = "Grazie, {name}. Aysa farebbe un inchino, Ji esulterebbe. Io, tutti e due. Male."
L["Thank you, {name}. I will think of you at my next meal, and the one after."] = "Grazie, {name}. Ti penserò al prossimo pasto, e a quello dopo."
L["Chen always said: never refuse a gift. Or a drink. Thank you, {name}."] = "Chen diceva sempre: mai rifiutare un dono. O un bicchiere. Grazie, {name}."
L["I was about to nap, {name}, but this is better. Slightly. Thank you."] = "Stavo per fare un pisolino, {name}, ma questo è meglio. Di poco. Grazie."
L["A hozen would have thrown something, {name}. I was raised better. Thank you."] = "Un hozen ti avrebbe tirato qualcosa, {name}. Io ho più educazione. Grazie."
L["Of course, {name}. Patience, and it is done. Patience is the slow part."] = "Certo, {name}. Un po' di pazienza, ed è fatto. La pazienza è la parte lenta."
L["With pleasure, {name}. A kind deed is never wasted."] = "Con piacere, {name}. Una buona azione non è mai sprecata."
L["At once, {name}. Quick for a pandaren, which is not saying much."] = "Subito, {name}. Veloce per un pandaren, il che non vuol dire molto."
L["Master Shang Xi said: help whoever asks, {name}. He also said: duck."] = "Maestro Shang Xi diceva: aiuta chi chiede, {name}. E anche: giù la testa!"
L["A Tushui master would make you meditate first, {name}. I will skip that part."] = "Un maestro Tushui ti farebbe prima meditare, {name}. Io salto questa parte."
L["Anything for you, {name}. Except the last dumpling. Let us not be silly."] = "Tutto per te, {name}. Tranne l'ultimo raviolo. Non esageriamo."
L["One {buff}, {name}, brewed strong. The recipe stays a secret."] = "{buff} per te, {name}, in infusione forte. La ricetta resta segreta."
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "Prendi, {name}. E dopo, magari, una tazza di tè?"
L["Balance in all things, {name}. Now go with a light heart."] = "Equilibrio in ogni cosa, {name}. Ora va' con il cuore leggero."
L["Take this, {name}. A grummle would sell it to you for a luckydo."] = "Prendi, {name}. Un grummle te lo venderebbe in cambio di un portafortuna."
L["The jinyu say the waters foretold this, {name}. They say that a lot."] = "I jinyu dicono che le acque l'avevano predetto, {name}. Lo dicono spesso."
L["The Huojin say act first. The Tushui say think first. I say: here, {name}."] = "Gli Huojin dicono: prima agisci. I Tushui: prima pensa. Io dico: tieni, {name}."
L["A pandaren stood up to give you this, {name}. Treasure it."] = "Un pandaren si è alzato per darti questo, {name}. Fanne tesoro."
L["Fight like a monk, {name}: calm, quick, and then a long lunch."] = "Combatti come un monaco, {name}: calma, rapidità, e poi un lungo pranzo."
L["Go gently, {name}. The turtle got where it was going and never hurried once."] = "Chi va piano va sano e va lontano, {name}. Chiedilo alla tartaruga."
L["We must share a brew when the road allows, {name}!"] = "Dobbiamo farci una birra quando la strada lo permette, {name}!"
L["Shen-zin Su would be proud of us both, {name}. Or asleep. Hard to tell."] = "Shen-zin Su sarebbe fiero di noi, {name}. O dormirebbe. Difficile dirlo."
L["Two pandaren together, {name}. Somewhere, an innkeeper just felt a chill."] = "Due pandaren insieme, {name}. Da qualche parte, un oste rabbrividisce."
L["Liu Lang would approve, {name}: two of us, both a long way from home."] = "Liu Lang approverebbe, {name}: noi due, così lontano da casa."
L["A fight, then a meal, {name}. That is the correct order. Never the reverse."] = "Prima si combatte, poi si mangia, {name}. Mai il contrario."
L["Stay together, {name}, like dumplings in a steamer. Warm, and ready."] = "Restiamo uniti, {name}, come ravioli nel cestello. Caldi e pronti."
L["We move as one, {name}. Slowly, perhaps, but as one."] = "Tutti come uno, {name}. Piano, magari, ma come uno."
L["Balance, {name}: one fights, one heals, and one carries the snacks. Me."] = "Equilibrio, {name}: uno combatte, uno cura, uno porta gli spuntini. Io."
L["If we fall, {name}, we fall together, and then we nap. Let us not."] = "Se cadiamo, {name}, cadiamo insieme, e poi un pisolino. Meglio di no."
L["Up before the tea, {name}? Brave. Here, instead of the tea."] = "In piedi prima del tè, {name}? Che coraggio. Tieni, al posto del tè."
L["Morning, {name}. First this, then breakfast, then the second breakfast."] = "Buongiorno, {name}. Prima questo, poi la colazione, poi la seconda colazione."
L["A new day, {name}, and nobody has spilled anything yet. Let us begin gently."] = "Un nuovo giorno, {name}, e nessuno ha ancora rovesciato niente. Cominciamo piano."
L["Past my first nap, {name}, and before my second. Quickly, while I'm awake."] = "Tra il primo pisolino e il secondo, {name}. Presto, finché ho gli occhi aperti."
L["Late, {name}. The brewmasters are asleep. The brews, I suspect, are not."] = "È tardi, {name}. I mastri birrai dormono. Le birre, sospetto, no."
L["Midnight snack time, {name}. This is the appetiser."] = "Spuntino di mezzanotte, {name}. Questo è l'antipasto."
L["Your kindness is noted, {name}. Dragons do not forget."] = "Non scorderò la tua gentilezza, {name}. I draghi non dimenticano."
L["Thank you, {name}. Returned on swift wings."] = "Grazie, {name}. Ricambio su ali veloci."
L["Wings, fire and scales, {name}, and still you thought I needed help. Touching."] = "Ali, fuoco e scaglie, {name}, e mi hai aiutato lo stesso. Commovente."
L["I would bow, {name}, but last time my wings cleared a table. Thank you."] = "Mi inchinerei, {name}, ma l'ultima volta le mie ali hanno sparecchiato. Grazie."
L["That goes straight into my hoard, {name}. Kind deeds are the only gold I keep."] = "Finisce dritto nel mio tesoro, {name}. Le buone azioni sono l'unico oro che conservo."
L["I was made to be a weapon, {name}. I much prefer this part. Thank you."] = "Dovevo essere un'arma, {name}. Preferisco di gran lunga questa parte. Grazie."
L["Thank you, {name}. Wrathion would have made a speech of it. I will not."] = "Grazie, {name}. Wrathion ci avrebbe fatto un discorso. Io no."
L["Returned with a little fire in it, {name}. Only a little. I am practising."] = "Ricambiato con un pizzico di fuoco, {name}. Solo un pizzico. Mi sto esercitando."
L["Very well, {name}. Stand still, I would hate to singe you."] = "Molto bene, {name}. Non muoverti, mi dispiacerebbe bruciacchiarti."
L["Granted, {name}. A dragon keeps its word."] = "Concesso, {name}. Un drago mantiene la parola."
L["Certainly, {name}. Stand clear of the tail."] = "Certo, {name}. Tieniti alla larga dalla coda."
L["Of course, {name}. Is this still how it is done? I was asleep for a while."] = "Certo, {name}. Si fa ancora così? Ho fatto un pisolino un po' lungo."
L["Gladly, {name}. All five dragonflights are in me, and all five say yes."] = "Volentieri, {name}. I cinque stormi che ho dentro dicono sì all'unanimità."
L["Right away, {name}. Dragon-sized help, in a conveniently smaller form."] = "Subito, {name}. Un aiuto da drago, in comodo formato tascabile."
L["Of course, {name}. Neltharion only gave orders. A request is much nicer."] = "Certo, {name}. Neltharion sapeva solo dare ordini. Chiedere è più gentile."
L["Take this, {name}. Even a dragon needs allies. Especially one this size."] = "Prendi, {name}. Anche a un drago servono alleati. Specie a uno così piccolo."
L["A gift from the Dragon Isles, {name}. Fly well."] = "Un dono dalle Isole dei Draghi, {name}. Buon volo."
L["Alexstrasza says every life is precious, {name}. I am starting with yours."] = "Alexstrasza dice che ogni vita è preziosa, {name}. Io comincio dalla tua."
L["I slept through ten thousand years of good deeds, {name}. Catching up now."] = "Ho diecimila anni di buone azioni arretrate, {name}. Comincio da qui."
L["Tell them a dragon did this, {name}. It sounds far grander than it was."] = "Di' a tutti che è stato un drago, {name}. Suona molto più epico di com'era."
L["Scalecommander's orders, {name}. I am not a Scalecommander, but still."] = "Ordine del Comandante delle Scaglie, {name}. Io non lo sono, ma suonava bene."
L["Take this, {name}. Ancient dragon magic, only slightly out of date."] = "Prendi, {name}. Antica magia draconica, appena un po' scaduta."
L["A dragon giving, {name}, not taking. I am trying something new."] = "Un drago che regala invece di accumulare, {name}. Sto sperimentando."
L["The Forbidden Reach feels far behind us now, {name}."] = "L'Isola Proibita ormai sembra così lontana, {name}."
L["Two dracthyr in one place, {name}. Mind the wings; there is not room for four."] = "Due dracthyr qui, {name}? Occhio alle ali: in quattro non ci stanno."
L["Remember when the whole world was new to us, {name}? It still is, mostly."] = "Ricordi quando il mondo intero ci era nuovo, {name}? Lo è ancora, quasi tutto."
L["In visage form nobody can tell, {name}. Between us: we look better in scales."] = "In sembianze mortali non si nota, {name}. Tra noi: con le scaglie stiamo meglio."
L["Tell me when to breathe fire, {name}. And, please, when not to."] = "Dimmi quando sputare fuoco, {name}. E, per favore, anche quando no."
L["I woke in a cave full of strangers, {name}. This is far better company."] = "Mi svegliai in una grotta di sconosciuti, {name}. Qui si sta molto meglio."
L["Neltharion made us to fight alone, {name}. We have improved on him."] = "Neltharion ci creò solitari, {name}. Abbiamo migliorato il progetto."
L["Stay clear of my tail, {name}. It hasn't yet learned whose side it's on."] = "Stai alla larga dalla mia coda, {name}. Non sa ancora da che parte sta."
L["A flight of our own, {name}. So this is what the dragons meant."] = "Uno stormo tutto nostro, {name}. Ecco cosa intendevano i draghi."
L["It is good to see one of our own, {name}."] = "È bello vedere qualcuno della nostra gente, {name}."
L["Our people are few, {name}. That makes each of us count."] = "Siamo in pochi, {name}. Per questo ognuno di noi conta."
L["Thank you, {name}. The Alliance looks after its own, and today that's me."] = "Grazie, {name}. L'Alleanza si prende cura dei suoi, e oggi tocca a me."
L["Kindness answered, {name}. For the Alliance!"] = "Gentilezza ricambiata, {name}. Per l'Alleanza!"
L["Stormwind has a statue for every hero, {name}. I'm putting in a word for yours."] = "Roccavento ha una statua per ogni eroe, {name}. Metto una buona parola per la tua."
L["The Alliance way, {name}: you help me, I help you, a dwarf buys the drinks."] = "Regola dell'Alleanza, {name}: tu aiuti me, io aiuto te, un nano paga da bere."
L["Genn would growl, Muradin would hug, {name}. I'll just return it."] = "Genn ringhierebbe, Muradin abbraccerebbe, {name}. Io ricambio e basta."
L["If the Alliance gave medals for manners, {name}, you'd need a second tabard."] = "Se l'Alleanza desse medaglie al galateo, {name}, ti servirebbe un'altra tabarda."
L["Returned in full, {name}. An ally who gives first is worth a whole garrison."] = "Ricambio per intero, {name}. Un alleato che dona per primo vale una guarnigione."
L["Of course, {name}. Allies help each other. It's practically in the name."] = "Certo, {name}. Gli alleati si aiutano a vicenda. Lo dice la parola stessa."
L["At once, {name}. The Alliance does not leave a friend wanting."] = "Subito, {name}. L'Alleanza non lascia un amico nel bisogno."
L["Of course, {name}. It's in the Alliance charter. Somewhere near the back."] = "Certo, {name}. È nello statuto dell'Alleanza. In una nota a piè di pagina."
L["By order of the Alliance, {name}: one {buff}, effective at once."] = "Per ordine dell'Alleanza, {name}: {buff}, con effetto immediato."
L["Anything for an ally, {name}. Within reason. This is well within reason."] = "Tutto per un alleato, {name}. Nei limiti del ragionevole. Questo ci rientra."
L["Right away, {name}. SI:7 knew you would ask. I only just found out."] = "Subito, {name}. Il SI:7 lo sapeva già. Io l'ho scoperto adesso."
L["For the Alliance, {name}! Stay strong out there. Stronger, now."] = "Per l'Alleanza, {name}! Resta forte là fuori. Anzi, ora più forte."
L["Onward, {name}. The Alliance is with you."] = "Avanti, {name}. L'Alleanza è con te."
L["Take this, {name}. Had a gnome made it, it would come with twelve levers."] = "Prendi, {name}. Se l'avesse fatto uno gnomo, avrebbe dodici leve."
L["Compliments of the Alliance, {name}. We've done these since the Second War."] = "Omaggio dell'Alleanza, {name}. Qualità garantita dalla Seconda Guerra."
L["Chin up, {name}. Somewhere in Stormwind, a bard is writing about this."] = "Su con la vita, {name}. A Roccavento un bardo sta già scrivendo di te."
L["Every ally counts, {name}. I counted, actually. You're my favourite so far."] = "Ogni alleato conta, {name}. Li ho contati davvero. Per ora sei in testa."
L["Anduin would want me to share, {name}, and I'd hate to disappoint him."] = "Anduin vorrebbe che condividessi, {name}, e non voglio deluderlo."
L["Together we stand, {name}. For the Alliance!"] = "Uniti siamo forti, {name}. Per l'Alleanza!"
L["Right, {name}: shields up, heads down, and nobody charges before the plan does."] = "Allora, {name}: scudi alti, testa bassa, e nessuno carica prima del piano."
L["The finest company the Alliance ever fielded, {name}. Or at least the nearest."] = "La miglior compagnia mai schierata dall'Alleanza, {name}. O almeno la più vicina."
L["Together, {name}, we're practically a regiment. A small, well-dressed regiment."] = "Insieme, {name}, siamo quasi un reggimento. Un reggimento piccolo ma elegante."
L["Watch each other's backs, {name}. The Alliance was built by people who did."] = "Guardiamoci le spalle, {name}. L'Alleanza è nata proprio così."
L["Strength and honour, {name}. And kindness, it turns out. Repaid in full."] = "Forza e onore, {name}. E gentilezza, a quanto pare. Ripagata per intero."
L["The Horde takes care of its own, {name}."] = "L'Orda non abbandona i suoi, {name}."
L["Strength given, strength returned, {name}. That's all of Horde diplomacy."] = "Forza data, forza resa, {name}. Ecco tutta la diplomazia dell'Orda."
L["I'd carve your name on Orgrimmar's gates, {name}, but they're full. Thanks."] = "Inciderei il tuo nome sulle porte di Orgrimmar, {name}, ma sono piene. Grazie."
L["Gallywix would've sent you an invoice, {name}. I'm sending this instead."] = "Gallywix ti avrebbe mandato una fattura, {name}. Io ti mando questo."
L["You did not have to do that, {name}. That is why the Horde remembers it."] = "Non dovevi farlo, {name}. Per questo l'Orda se lo ricorda."
L["In the Horde we do not say thank you twice, {name}. So: once, and meant."] = "Nell'Orda non si dice grazie due volte, {name}. Quindi: una, e sentita."
L["Consider it done, {name}. For the Horde, and for anyone who asks nicely."] = "Consideralo fatto, {name}. Per l'Orda, e per chiunque chieda con gentilezza."
L["You only had to ask, {name}. The Horde answers."] = "Bastava chiedere, {name}. L'Orda risponde."
L["The Horde usually helps with axes, {name}. Today, {buff}."] = "Di solito l'Orda aiuta a colpi d'ascia, {name}. Oggi con {buff}."
L["Done, {name}. No speeches. The Horde has plenty of those already."] = "Fatto, {name}. Niente discorsi. L'Orda ne ha già fin troppi."
L["You asked, {name}. In Orgrimmar, that counts as a formal treaty."] = "Hai chiesto, {name}. A Orgrimmar vale come un trattato ufficiale."
L["Asking is no weakness, {name}. Refusing an ally would be."] = "Chiedere non è debolezza, {name}. Rifiutare un alleato sì."
L["For the Horde, {name}! Go with strength. I've just handed you some."] = "Per l'Orda, {name}! Va' e sii forte. La forza te l'ho appena data."
L["Go with honour, {name}. Victory awaits."] = "Va' con onore, {name}. La vittoria ti attende."
L["Go and do something worth a song, {name}. Loud songs. The Horde likes loud."] = "Fa' qualcosa che meriti una canzone, {name}. Da urlare: all'Orda piace forte."
L["Walk tall, {name}. The Horde always made room for those the world turned away."] = "Cammina a testa alta, {name}. L'Orda ha sempre accolto chi il mondo respingeva."
L["Take this, {name}, and a word of Horde wisdom: hit first, apologise never."] = "Prendi, {name}, e un detto dell'Orda: prima si colpisce, le scuse mai."
L["Victory or death, {name}. I'd prefer victory, so take this."] = "Vittoria o morte, {name}. Preferisco la vittoria, quindi prendi."
L["Like a mak'gora, {name}, except everybody wins. Here."] = "Come un mak'gora, {name}, ma vincono tutti. Tieni."
L["Our strength is each other, {name}. For the Horde!"] = "La nostra forza siamo noi, {name}. Per l'Orda!"
L["Forward, {name}. The Horde advances together. Retreats... never, officially."] = "Avanti, {name}. L'Orda avanza unita. Ritirate... mai, ufficialmente."
L["Together we're a war band, {name}. Apart, we're just loud."] = "Insieme siamo un esercito, {name}. Divisi, solo baccano."
L["Shoulder to shoulder, {name}. Whoever charges first buys the grog."] = "Spalla a spalla, {name}. Chi carica per primo paga il grog."
L["Nobody gets left behind, {name}. I've counted us twice."] = "Nessuno resta indietro, {name}. Ci ho contati due volte."
L["Thank you, {name}. Good hearts turn up on every side, and apparently here."] = "Grazie, {name}. I cuori buoni si trovano ovunque, e a quanto pare anche qui."
L["Thank you, {name}. No side, no title, just kindness. Legends start like this."] = "Grazie, {name}. Né fazione né titoli, solo gentilezza. Così nascono le leggende."
L["Thank you, {name}. Kindness has no faction, which is handy, since I have none."] = "Grazie, {name}. La gentilezza non ha fazione. Comodo: nemmeno io."
L["Thank you, {name}. Whichever side gets you is getting a bargain."] = "Grazie, {name}. La fazione che ti prenderà farà un affarone."
L["Whoever claims me in the end, {name}, I'll remember you first. Thank you."] = "Da qualunque parte io finisca, {name}, mi ricorderò prima di te. Grazie."
L["Strictly neutral, {name}, but gratitude doesn't count. Thank you."] = "Rigorosamente neutrale, {name}, ma la gratitudine non conta. Grazie."
L["Gladly, {name}, whatever banner you fly. I don't even own a banner."] = "Con piacere, {name}, qualunque sia il tuo stendardo. Io non ne ho."
L["Certainly, {name}. I help everyone. It's the one thing I've decided."] = "Certo, {name}. Aiuto tutti. È l'unica cosa che ho deciso."
L["Everyone asks me which side I'm on, {name}. Much nicer to be asked for help."] = "Tutti mi chiedono da che parte sto, {name}. Farmi chiedere aiuto è molto meglio."
L["Of course, {name}. No war council to ask; just me, and I say yes."] = "Certo, {name}. Niente consiglio di guerra: decido io, e dico sì."
L["Here you are, {name}. No oath, no colours, no fee."] = "Ecco, {name}. Senza giuramenti, bandiere o tariffe."
L["Friends can come from any side, {name}. Or, like me, from none in particular."] = "Gli amici vengono da ogni parte, {name}. O, come me, da nessuna in particolare."
L["Soon they'll hand us tabards, {name}. Until then, we look after each other."] = "Presto ci daranno le tabarde, {name}. Fino ad allora, badiamo l'uno all'altro."
L["I haven't chosen a side yet, {name}, so I'm being kind to both. Take this."] = "Non ho ancora scelto una fazione, {name}: sono gentile con entrambe. Prendi."
L["A gift with no strings, {name}. I don't even have a faction to tie them to."] = "Un dono senza lacci né lacciuoli, {name}. Non ho una fazione a cui legarli."
L["Go on, {name}. Two whole factions are waiting to argue over us."] = "Vai, {name}. Ci sono due fazioni intere pronte a contenderci."
L["No quartermaster yet, {name}, so nobody's counting. Have plenty."] = "Niente furiere per ora, {name}: nessuno conta. Prendine a volontà."
L["Side by side, {name}, whatever comes."] = "Fianco a fianco, {name}, qualunque cosa accada."
L["No flag over this party, {name}, just us. That's plenty."] = "Nessuna bandiera qui, {name}: solo noi. Basta e avanza."
L["One day we'll pick sides, {name}. Today we pick fights, together."] = "Un giorno sceglieremo con chi stare, {name}. Oggi, chi picchiare."
L["Whatever side the rest of the world is on, {name}, I'm on this party's."] = "Il mondo scelga pure la sua parte, {name}. Io sto con questo gruppo."
L["Neutral in the war, {name}, but very partial to this group."] = "Neutrale in guerra, {name}, ma per questo gruppo sono di parte."
L["One good turn deserves another, {name}."] = "Una cortesia ne merita un'altra, {name}."
L["Have some {buff} in return, {name}."] = "In cambio, ecco {buff} per te, {name}."
L["Kindness should go both ways, {name}. Thank you."] = "La gentilezza va ricambiata, {name}. Grazie."
L["You went first, {name}, so I'll go second and we'll call it friendship."] = "Prima mossa tua, {name}, seconda mia. Chiamiamola amicizia."
L["I'd write you a song, {name}, but {buff} is less off-key."] = "Ti scriverei una canzone, {name}, ma con {buff} stono meno."
L["A gift for a gift, {name}. At this rate we'll be unstoppable by supper."] = "Dono per dono, {name}. Di questo passo, per cena saremo inarrestabili."
L["All square, {name}. Unless you'd like to make it best of three."] = "Pari e patta, {name}. O vuoi giocarti la bella?"
L["You started it, {name}. I'm only finishing it."] = "Hai cominciato tu, {name}. Io finisco e basta."
L["That was kind, {name}. The day just got noticeably better. Here's my half."] = "Che gentile, {name}. La giornata è appena migliorata. Ecco la mia metà."
L["You asked, {name}, and here it is."] = "Hai chiesto, {name}, ed ecco fatto."
L["{buff}, coming right up, {name}."] = "{buff} in arrivo, {name}."
L["Gladly, {name}. One moment."] = "Con piacere, {name}. Un attimo."
L["Asked and answered, {name}. Next question?"] = "Chiesto e fatto, {name}. Prossima domanda?"
L["Say the word and it's yours, {name}. You said several. Here."] = "Basta una parola, {name}, e tu ne hai dette parecchie. Ecco."
L["For you, {name}? Gladly. I was hoping someone would ask."] = "Per te, {name}? Volentieri. Speravo che qualcuno lo chiedesse."
L["Of course, {name}. Easiest yes I'll say all day."] = "Certo, {name}. Il sì più facile di tutta la giornata."
L["Right away, {name}. Finally, a question I know the answer to."] = "Subito, {name}. Finalmente una domanda di cui so la risposta."
L["Safe travels, {name}. {buff} packs lighter than a sword."] = "Buon viaggio, {name}. {buff} pesa meno di una spada."
L["A small blessing for the road, {name}."] = "Una piccola benedizione per il viaggio, {name}."
L["Go well, {name}, and come back in one piece."] = "Buon cammino, {name}, e torna senza un graffio."
L["No reason, {name}. It just felt like a {buff} sort of day."] = "Nessun motivo, {name}. Oggi è una giornata da {buff}."
L["Don't mind me, {name}. Just passing, with a spare {buff}."] = "Non badare a me, {name}. Passavo di qui con {buff} d'avanzo."
L["Consider it a gift, {name}. I'd wrap it, but it glows through the paper."] = "È un regalo, {name}. Lo incarterei, ma brilla attraverso la carta."
L["Here, {name}. Pass it on when you meet someone who needs it."] = "Tieni, {name}. Passalo a chi ne avrà bisogno."
L["Whatever brings you here, {name}, may it go better than planned."] = "Qualunque cosa ti porti qui, {name}, che vada meglio del previsto."
L["Just being neighbourly, {name}. Very, very temporary neighbours."] = "Buon vicinato, {name}. Vicini molto, molto temporanei."
L["Everyone ready? You are now, {name}."] = "Tutti pronti? Ora lo sei anche tu, {name}."
L["A little something for the party, {name}."] = "Un pensierino per il gruppo, {name}."
L["Stay close, {name}. We go further together."] = "Stammi vicino, {name}. Insieme si va più lontano."
L["House rules, {name}: nobody dies, nobody sulks, everybody eats after."] = "Regole, {name}: niente morti, niente musi lunghi, e dopo tutti a tavola."
L["There, {name}. Now if this goes badly, it won't be my fault."] = "Ecco, {name}. Ora, se va male, non sarà colpa mia."
L["All set, {name}. I'd give a speech, but we'd be here all day."] = "Pronti, {name}. Farei un discorso, ma staremmo qui fino a sera."
L["Look after that, {name}. It's the only one I brought for you."] = "Abbine cura, {name}. È l'unico che ho portato per te."
L["Now we look the part, {name}. Let's go and be it."] = "Ora sembriamo eroi, {name}. Andiamo a esserlo davvero."
L["Fresh {buff} all round, {name}. The rest is luck and elbows."] = "{buff} per tutti, {name}. Il resto è fortuna e gomitate."
L["Thank you, {name}. I'd conjure a gift in return, but it would only be water."] = "Grazie, {name}. Ti evocherei un regalo, ma verrebbe fuori solo acqua."
L["Much obliged, {name}. I'll write it up properly later. Several pages."] = "Grazie mille, {name}. Poi ne farò una relazione. Di parecchie pagine."
L["Thank you, {name}. They never taught gratitude at Dalaran. I'm self-taught."] = "Grazie, {name}. A Dalaran la gratitudine non si insegna. Sono autodidatta."
L["Kind of you, {name}. I'd say it went to my head, but that's my job."] = "Che gentile, {name}. Mi darebbe alla testa, ma la testa è il mio mestiere."
L["Of course, {name}. And yes, I suppose you'll want water as well."] = "Certo, {name}. E sì, immagino che vorrai anche l'acqua."
L["As requested, {name}. Side effects may include footnotes."] = "Come da richiesta, {name}. Può causare note a piè di pagina."
L["At once, {name}. Carefully, too; I've blinked into two walls today."] = "Subito, {name}. Con calma: oggi con la Traslazione ho già preso due muri."
L["Gladly, {name}. Knowledge should be shared. The Kirin Tor say so, reluctantly."] = "Con piacere, {name}. Il sapere va condiviso. Lo dice il Kirin Tor, a malincuore."
L["Here, {name}. I had a spare thought and nowhere to put it."] = "Tieni, {name}. Mi avanzava un pensiero, e non sapevo dove metterlo."
L["Take this, {name}. I'd add bread, but conjured bread tastes of nothing."] = "Prendi, {name}. Ci aggiungerei il pane, ma quello evocato non sa di niente."
L["{buff} for you, {name}. No charge, unlike the portals."] = "{buff} per te, {name}. Gratis, non come i portali."
L["Here, {name}. Most folk I point at turn into sheep. Today's your lucky day."] = "Tieni, {name}. Di solito chi punto diventa una pecora. Oggi ti è andata bene."
L["Nothing on fire, nothing frozen, {name}. I'm branching out."] = "Niente fuoco, niente gelo, {name}. Sto ampliando il repertorio."
L["Now that you're clever, {name}, stand between me and the angry things."] = "Ora che sei un genio, {name}, mettiti tra me e quelli arrabbiati."
L["For the record, {name}, I only blink away when it's tactically sound."] = "Per la cronaca, {name}, scappo con la Traslazione solo per motivi tattici."
L["There, {name}. Wiser already: look, you're standing further from me."] = "Ecco, {name}. Funziona già: vedi come prendi le distanze da me?"
L["Minds sharpened, {name}. I'll handle the fire, the frost and the panicking."] = "Menti affilate, {name}. Io penso a fuoco, gelo e panico."
L["How thoughtful, {name}. The Light keeps accounts; I settle mine early."] = "Che premura, {name}. La Luce tiene i conti, e io pago in anticipo."
L["Thank you, {name}. I'll put in a good word with the Light. It owes me several."] = "Grazie, {name}. Metterò una buona parola con la Luce. Me ne deve parecchie."
L["Thank you, {name}. A small miracle, and I didn't even have to pray for it."] = "Grazie, {name}. Un piccolo miracolo, e non ho nemmeno dovuto pregare."
L["Thank you, {name}. My faith in people is restored. It was only resting."] = "Grazie, {name}. La mia fede nel prossimo è tornata. Stava solo riposando."
L["Of course, {name}. The Light keeps no hours, and neither, sadly, do I."] = "Certo, {name}. La Luce non ha orari, e purtroppo nemmeno io."
L["Straight away, {name}. Most prayers take longer; you've found a shortcut."] = "Subito, {name}. Le preghiere sono più lente: hai trovato la scorciatoia."
L["Certainly, {name}. The Light shines on those who ask. I just aim it."] = "Certo, {name}. La Luce splende su chi chiede. Io mi limito a puntarla."
L["With pleasure, {name}. Faith moves mountains; I'm starting smaller."] = "Con piacere, {name}. La fede sposta le montagne; io parto dai sassi."
L["Bless you, {name}. No, you didn't sneeze; I'm simply thorough."] = "Salute, {name}! No, non hai starnutito: te la regalo e basta."
L["Here, {name}. Think of it as a prayer that arrived early."] = "Tieni, {name}. Consideralo una preghiera esaudita in anticipo."
L["The Light asked me to pass this along, {name}. I'm paraphrasing."] = "La Luce mi ha chiesto di passartelo, {name}. Più o meno."
L["Take this, {name}. It saves us both an awkward resurrection later."] = "Prendi, {name}. Ci risparmia una resurrezione imbarazzante più tardi."
L["Freely given, {name}. Faith costs nothing. The robes, sadly, did."] = "Dato gratis, {name}. La fede non costa nulla. Le vesti, purtroppo, sì."
L["Your turn, {name}. Now, I beg you all: make my job boring."] = "A te, {name}. E ora vi supplico tutti: fatemi annoiare."
L["Everyone stay near me, {name}. The Light has a limited range."] = "State tutti vicino a me, {name}. La Luce ha una portata limitata."
L["There, {name}. If anyone falls, I'll be very disappointed, then fix it."] = "Ecco, {name}. Se qualcuno cade, ci resterò molto male, poi rimedierò."
L["Done, {name}. I'll be at the back, praying loudly."] = "Fatto, {name}. Sarò in fondo, a pregare ad alta voce."
L["Thank you, {name}. I'd purr, but I'm not in the right shape for it."] = "Grazie, {name}. Farei le fusa, ma non sono nella forma giusta."
L["Thanks, {name}. My bear form sends a grateful grunt."] = "Grazie, {name}. La mia forma d'orso grugnisce riconoscente."
L["Much obliged, {name}. My cat form wants to bring you a rabbit. I've said no."] = "Grazie, {name}. La mia forma felina voleva portarti un coniglio. Le ho detto no."
L["Thank you, {name}. I'll plant a tree in your honour. Give it a century."] = "Grazie, {name}. Pianterò un albero in tuo onore. Dagli un secolo."
L["Certainly, {name}. Give me a moment to remember which shape has hands."] = "Certo, {name}. Un attimo che ricordo quale forma ha le mani."
L["Of course, {name}. Hold still, like an oak. Oaks are wonderful at it."] = "Certo, {name}. Immobile come una quercia: le querce sono campionesse."
L["Gladly, {name}. The wild shares everything. Well, not the bears."] = "Con piacere, {name}. La natura condivide tutto. Be', gli orsi no."
L["Right away, {name}. Pardon the feathers; I've just come from being an owl."] = "Subito, {name}. Scusa le piume: fino a poco fa ero un gufo."
L["Fresh from the Emerald Dream, {name}. Sorry if I yawn."] = "Vengo dal Sogno di Smeraldo, {name}. Scusa se sbadiglio."
L["Take this, {name}. Nature provides, and I'm its errand runner today."] = "Prendi, {name}. La natura provvede, e oggi le consegne le faccio io."
L["The wild calls you friend now, {name}. Handy, since most of it has teeth."] = "Ora la natura è tua amica, {name}. Comodo, visto che quasi tutta ha i denti."
L["I brought you flowers as well, {name}, but I was a stag at the time. Sorry."] = "Avevo anche dei fiori per te, {name}, ma ero un cervo. Li ho mangiati."
L["Here, {name}. Cenarius would want you to have it. I'm nearly sure."] = "Tieni, {name}. Cenarius vorrebbe che fosse tuo. Quasi di sicuro."
L["Ready, {name}? Now, whatever happens, nobody startle the bear."] = "Pronti, {name}? Qualunque cosa accada, nessuno spaventi l'orso."
L["There, {name}. I'll be the cat, the bear or, if we must swim, the seal."] = "Ecco, {name}. Farò il gatto, l'orso o, se c'è da nuotare, la foca."
L["I've one rebirth in me, {name}. Please, nobody make me choose."] = "Ho una sola Rinascita, {name}. Vi prego, non fatemi scegliere."
L["Close ranks, {name}. The forest is watching, and it's rooting for us."] = "Ranghi serrati, {name}. La foresta tifa per noi con tutte le radici."
L["Kindness, {name}? My favourite virtue. Just ahead of polishing."] = "Gentilezza, {name}? La mia virtù preferita. Seguita dalla lucidatura."
L["For that, {name}, my best blessing. Not the second best. The best."] = "Per te, {name}, la benedizione migliore. Non la seconda. La migliore."
L["Virtue rewarded on the spot, {name}! I do love it when that happens."] = "Virtù premiata all'istante, {name}! Adoro quando succede."
L["Thank you, {name}. My oath says to repay kindness. I'd do it anyway."] = "Grazie, {name}. Il mio giuramento impone di ricambiare. Lo farei comunque."
L["By the Light, {name}, of course! I've been hoping somebody would ask."] = "Per la Luce, {name}, certo! Speravo proprio che qualcuno me lo chiedesse."
L["You have my blessing, {name}. Literally, this time."] = "Hai la mia benedizione, {name}. Stavolta alla lettera."
L["Certainly, {name}. Kneel if you like. I won't insist. I'll be delighted."] = "Certo, {name}. Inginocchiati, se vuoi. Non insisto. Però mi farebbe piacere."
L["Gladly, {name}. I never run short of blessings. Mana, now and then."] = "Volentieri, {name}. Benedizioni ne ho sempre. Mana, non sempre."
L["The Light asks nothing in return, {name}. I, however, accept thanks."] = "La Luce non chiede nulla in cambio, {name}. Io, però, accetto un grazie."
L["Go with the Light, {name}. I'll be right behind you, clanking."] = "Va' con la Luce, {name}. Io sarò subito dietro di te, sferragliando."
L["The blessing's free, {name}. You've been spared the sermon. This time."] = "La benedizione è gratis, {name}. Il sermone te lo risparmio. Per stavolta."
L["There, {name}. It won't last forever, so be heroic while it does."] = "Ecco, {name}. Non è per sempre: compi gesta eroiche finché dura."
L["Stand tall, {name}. The Light walks with you, and it has excellent posture."] = "Testa alta, {name}. La Luce cammina con te, e ha un portamento impeccabile."
L["You're blessed, {name}. If I bubble later, it's strictly tactical."] = "Benedizione fatta, {name}. Se poi faccio la bolla, è solo tattica."
L["Stand fast, {name}. We have the Light, and I have a very large hammer."] = "Tenete duro, {name}. Abbiamo la Luce, e io ho un martello molto grosso."
L["One blessing each, {name}. The Light is generous, but it insists on turns."] = "Una benedizione a testa, {name}. La Luce è generosa, ma pretende i turni."
L["Splendid, {name}. Now, nobody look directly at me. I'm rather bright today."] = "Splendido, {name}. Ora non guardatemi dritto: oggi splendo parecchio."
L["How kind, {name}. My imp says thank you too. He's lying, but I'm not."] = "Che gentile, {name}. Anche il mio imp ti ringrazia. Mente, ma io no."
L["Thank you, {name}. It's been ages since anyone gave me something uncursed."] = "Grazie, {name}. Da secoli nessuno mi regalava qualcosa di non maledetto."
L["Thank you, {name}. I'll repay you with something I didn't find in a crypt."] = "Grazie, {name}. Ti ripagherò con qualcosa che non ho trovato in una cripta."
L["Most gracious, {name}. I've asked the voidwalker to stop looming at you."] = "Troppo gentile, {name}. Ho detto al Viandante del Vuoto di non fissarti."
L["Of course, {name}. No soul required. This time."] = "Certo, {name}. Nessuna anima richiesta. Per stavolta."
L["You asked a warlock for help, {name}. Bold. I like you already."] = "Chiedere aiuto a chi evoca demoni, {name}? Che fegato. Mi piaci già."
L["Of course, {name}. The imp offered to help, and I said no, for all our sakes."] = "Certo, {name}. L'imp voleva aiutare. Gli ho detto di no, per il bene di tutti."
L["Certainly, {name}. Of all my spells, this is the one I can do at parties."] = "Certo, {name}. Dei miei incantesimi, è l'unico presentabile alle feste."
L["Here, {name}. Don't ask where it came from. Really, don't."] = "Tieni, {name}. Non chiedermi da dove viene. Davvero, non farlo."
L["Fall in a lake someday, {name}, and you'll think of me fondly."] = "Se un giorno cadrai in un lago, {name}, penserai a me con affetto."
L["Breathe easy, {name}. I'd hate to lose you to anything as dull as water."] = "Respira pure, {name}. Perderti per colpa dell'acqua sarebbe così banale."
L["Here, {name}. You'll want a soulstone too, but that's a bigger conversation."] = "Tieni, {name}. Per la Pietra dell'Anima ci vorrà un discorso a parte."
L["Take this, {name}. It's the only spell of mine the priests approve of."] = "Prendi, {name}. È l'unico mio incantesimo che i sacerdoti approvano."
L["Everyone ready, {name}? Souls intact? Good. Let's keep it that way."] = "Tutti pronti, {name}? Anime intatte? Bene. Teniamole così."
L["Stay close, {name}. The voidwalker takes the hits; I take the credit."] = "Stammi vicino, {name}. I colpi li prende il Viandante, i meriti io."
L["Swim all you like, {name}. If anyone drifts off, I'll summon them back."] = "Nuota quanto vuoi, {name}. Chi si perde, lo evoco indietro."
L["Do pet the felhunter, {name}. Just take your spells off first."] = "Accarezza pure il Vilsegugio, {name}. Ma prima togliti gli incantesimi."
L["Thank you, {name}! Sorry, was that loud? I only have the one volume."] = "Grazie, {name}! Scusa, ho urlato? Ho un solo volume."
L["Much obliged, {name}. No spells to give back, but I do a very sincere shout."] = "Grazie mille, {name}. Incantesimi non ne ho, ma faccio un urlo sincerissimo."
L["Thanks, {name}. Now I'm twice as angry. In the good way."] = "Grazie, {name}. Ora ho il doppio della rabbia. In senso buono."
L["Thanks, {name}. You've earned a place right behind me. Safest spot there is."] = "Grazie, {name}. Hai un posto dietro di me: il più sicuro che ci sia."
L["You want a shout, {name}? I was going to shout anyway."] = "Vuoi un urlo, {name}? Tanto avrei urlato comunque."
L["Of course, {name}. Cover your ears; this is the only way I know how."] = "Certo, {name}. Tappati le orecchie: è l'unico modo che conosco."
L["Right away, {name}. Stay in earshot. For me that's a generous distance."] = "Subito, {name}. Resta a portata d'orecchio. Con me è una bella distanza."
L["Happily, {name}! Words aren't my strength. Volume is."] = "Subito, {name}! Le parole non sono il mio forte. Il volume sì."
L["Consider yourself shouted at, {name}. Affectionately."] = "Ti ho appena urlato addosso, {name}. Con affetto."
L["No incense, no prayers, {name}. Just me, shouting encouragingly."] = "Niente incenso, niente preghiere, {name}. Solo urla d'incoraggiamento."
L["Chin up, {name}! If anything bothers you, I'll charge it."] = "Su con la vita, {name}! Se qualcosa ti dà fastidio, lo carico."
L["There, {name}! Anything that doesn't feel braver now wasn't listening."] = "Ecco, {name}! Chi non si sente più coraggioso ora, non stava ascoltando."
L["Here, {name}, some courage. Warriors make it by yelling. Don't ask how."] = "Tieni, {name}: coraggio. I guerrieri lo fanno a urla. Non chiedere come."
L["Listen up, {name}! That's it. That was the whole speech."] = "Ascoltatemi, {name}! Ecco. Era tutto il discorso."
L["Where's the danger, {name}? Never mind, I'll find it. Face first."] = "Dov'è il pericolo, {name}? Niente, lo trovo io. Con la faccia."
L["Right, {name}! I go first, I shout loudest, and nobody touches the healer."] = "Bene, {name}! Io entro prima, urlo più forte, e nessuno tocca il guaritore."
L["Everybody angrier? Good. Onward, {name}, and mind my backswing."] = "Tutti più arrabbiati? Bene. Avanti, {name}, e occhio al mio rovescio."
L["A sharper mind for you, {name}. Mine cost me an eyebrow in Dalaran."] = "Una mente più acuta, {name}. La mia costò un sopracciglio a Dalaran."
L["More mana for you, {name}. Try not to spend it all on one fireball."] = "Più mana per te, {name}. Non spenderlo tutto in una Palla di Fuoco."
L["Thoughts humming, {name}? Normal. If they hum back, come and find me."] = "Pensieri che ronzano, {name}? Normale. Se ti rispondono, cercami."
L["A little arcane for your thoughts, {name}. Keep the change."] = "Un po' d'arcano per i tuoi pensieri, {name}. Tieni il resto."
L["Brilliance, bottled, {name}. The Kirin Tor would charge you for the bottle."] = "Brillantezza in bottiglia, {name}. Il Kirin Tor ti farebbe pagare il vuoto."
L["Sharper wits, {name}. Spend them on spells, locks or riddles; I won't judge."] = "Più acume, {name}. Usalo per incantesimi, serrature o indovinelli: non giudico."
L["Fortitude, {name}: a priest's polite way of saying 'stand in front'."] = "Fermezza, {name}: in sacerdotese vuol dire 'mettiti davanti'."
L["Every bit of stamina is one less panicked prayer from me, {name}."] = "Ogni punto di tempra è una preghiera disperata in meno per me, {name}."
L["Tougher already, {name}. Please don't take that as a dare."] = "Già più resistente, {name}. Non prenderla come una sfida."
L["There are other Power Words, {name}. 'Shield', and in emergencies, 'Run'."] = "Ci sono altre Parole del Potere, {name}: 'Scudo' e, in emergenza, 'Scappa'."
L["Sturdier now, {name}. Falls, bears and bad decisions all hurt a bit less."] = "Ora cadute, orsi e cattive decisioni fanno un po' meno male, {name}."
L["{buff}, {name}. Three words where 'be tougher' would do."] = "{buff}, {name}. Tante parole, quando bastava 'tieni duro'."
L["Consider your spirits lifted, {name}. Divinely, as it happens."] = "Spirito sollevato, {name}. Divinamente, per giunta."
L["Like a good night's sleep, {name}, without all the lying down."] = "Come una bella dormita, {name}, ma senza doversi sdraiare."
L["A second helping of spirit, {name}. The Light always insists on seconds."] = "Un altro po' di spirito, {name}. La Luce è come la nonna: il bis è d'obbligo."
L["Keep your spirit where it is, {name}. The Spirit Healers are busy enough."] = "Lo spirito tienilo dov'è, {name}: i Guaritori degli Spiriti sono già oberati."
L["Proof against shadow, {name}. I know its tricks; I've borrowed a few."] = "A prova d'ombra, {name}. Conosco i suoi trucchi: ne ho usati un paio."
L["Should the Void call, {name}, you can now pretend you're out."] = "Se il Vuoto chiama, {name}, ora puoi fingere di non essere in casa."
L["For when the dark gets personal, {name}. It usually does."] = "Per quando il buio ce l'ha con te, {name}. Capita spesso."
L["The shadows will have to knock first now, {name}."] = "Ora le ombre dovranno bussare prima di entrare, {name}."
L["Marked by the wild, {name}. The deer will tip their antlers as you pass."] = "Marchio della natura, {name}. Al tuo passaggio i cervi chineranno le corna."
L["You may smell faintly of moss, {name}. That's how you know it's working."] = "Potresti sapere un po' di muschio, {name}. È così che capisci che funziona."
L["Mark of the Wild, {name}. The wolves will still bite, but they'll feel bad."] = "Il marchio della natura, {name}. I lupi morderanno lo stesso, ma con rimorso."
L["The wild's own seal of approval, {name}. The squirrels were consulted."] = "Marchio di qualità della natura, {name}. Sentito il parere degli scoiattoli."
L["A little of the wild in you now, {name}. Resist the urge to howl."] = "Un po' di selvaggio in te, {name}. Trattieni la voglia di ululare."
L["Hide, claw and a thick coat, {name}. The wild packs light but thorough."] = "Pelle, artigli e pelliccia, {name}. La natura viaggia leggera, ma completa."
L["Anything that bites you now gets a mouthful, {name}."] = "Chi ti morde, {name}, avrà la bocca piena di spine."
L["Let the boar charge, {name}. It'll leave with regrets and splinters."] = "Lascia caricare il cinghiale, {name}. Ripartirà con rimpianti e schegge."
L["Like a rose, {name}: lovely to look at, a mistake to grab."] = "Non c'è rosa senza spine, {name}. E ora nemmeno tu."
L["Thorns, {name}. I grew them myself, so do be polite to them."] = "Spine, {name}. Le ho coltivate io, quindi sii gentile con loro."
L["Blessing of Kings, {name}. No crown, no throne, no taxes owed."] = "Benedizione dei Re, {name}. Niente corona, trono o tasse."
L["Long may you reign, {name}. For the next while, anyway."] = "Lungo regno a te, {name}. Almeno per i prossimi minuti."
L["A little more of everything, {name}. Kings never did settle for less."] = "Un po' di più in tutto, {name}. I re non si sono mai accontentati."
L["A king's blessing, {name}. Worn by better heads than mine, and some worse."] = "Benedizione da re, {name}. Portata da teste migliori della mia. E peggiori."
L["Every strength a little higher, {name}. Kings like to hedge their bets."] = "Tutto un po' più forte, {name}. I re tengono sempre il piede in più staffe."
L["Crown not included, {name}. Everything else is, a little."] = "Corona non inclusa, {name}. Tutto il resto sì, un pochino."
L["Might doesn't make right, {name}, but it does help the argument."] = "La forza non ti dà ragione, {name}, ma nelle discussioni aiuta."
L["A firmer swing for you, {name}. The Light loves a good follow-through."] = "Un colpo più deciso, {name}. La Luce ama chi va fino in fondo."
L["Stronger arms, {name}. Kindly point them at something that deserves it."] = "Braccia più forti, {name}. Puntale, per favore, su chi se lo merita."
L["Blessing of Might, {name}. It'll surprise you. It'll surprise them far more."] = "Benedizione della Potenza, {name}. Sorprenderà te. E loro molto di più."
L["Swing away, {name}. The Light will take the credit if it goes well."] = "Colpisci pure, {name}. Se va bene, il merito se lo prende la Luce."
L["Hit harder, {name}. Them, I mean. Not me. Never the paladin."] = "Picchia più forte, {name}. Loro, eh. Non me. Mai chi ti benedice."
L["Wisdom for you, {name}. I kept a little back for myself. Very little."] = "Saggezza per te, {name}. Un po' l'ho tenuta per me. Pochissima."
L["Wisdom for your mana, {name}. The other kind still comes from bad decisions."] = "Saggezza per il tuo mana, {name}. L'altra si impara ancora dagli errori."
L["Your mana creeps back on its own now, {name}, like a cat that's forgiven you."] = "Ora il mana torna da solo, {name}, come un gatto che ti ha perdonato."
L["Fewer sips between fights, {name}. The innkeepers will be heartbroken."] = "Meno bevute tra uno scontro e l'altro, {name}. I locandieri piangeranno."
L["Drink less, cast more, {name}. The Light's own budget advice."] = "Bevi meno, lancia di più, {name}. Consigli di risparmio dalla Luce."
L["Blessing of Wisdom, {name}: the one blessing that pays for itself."] = "Benedizione della Saggezza, {name}: l'unica che si ripaga da sola."
L["A blessing of quiet, {name}. Monsters will forget whose fault it was."] = "Benedizione di quiete, {name}. I mostri scorderanno di chi era la colpa."
L["Blessing of Salvation, {name}. You are now somebody else's problem."] = "Benedizione della Salvezza, {name}. Ora sei un problema di qualcun altro."
L["Saved, {name}. Not your soul, mind. Just your hide."] = "In salvo, {name}. Non l'anima, bada. Solo la pelle."
L["Hit hard, {name}. If anything turns round, look innocent. The Light will."] = "Colpisci forte, {name}. Se qualcosa si gira, fai l'innocente. Come la Luce."
L["The Light will find you easier now, {name}. Try not to squint."] = "Ora la Luce ti trova meglio, {name}. Non strizzare gli occhi."
L["Holy Light lands harder on you now, {name}. Please don't make me prove it."] = "Ora Luce Sacra ti cura di più, {name}. Non costringermi a dimostrarlo."
L["You'll heal easier, {name}. The Light appreciates a willing patient."] = "Guarirai meglio, {name}. La Luce apprezza i pazienti collaborativi."
L["Blessing of Light, {name}. Saving you is simpler now. Not that you'll need it."] = "Benedizione della Luce, {name}. Salvarti ora è più facile. Non che ti servirà."
L["Block a blow now, {name}, and the Light hits back for you. It's petty."] = "Para un colpo, {name}, e la Luce risponde per te. È permalosa."
L["Every blow lands softer now, {name}. Complaints go to the Light."] = "Ogni colpo fa meno male, {name}. Reclami alla Luce."
L["All the shelter of a temple, {name}, and none of the roof repairs."] = "Tutto il riparo di un tempio, {name}, senza le spese del tetto."
L["Claim sanctuary, {name}. It's easier when you bring your own."] = "Rifugiati nel santuario, {name}. È più facile se te lo porti dietro."
L["Instructions, {name}: hit things harder. There is no page two."] = "Istruzioni, {name}: colpisci più forte. Non c'è una seconda pagina."
L["Your sword arm is sorted, {name}. For the rest of you, see a priest."] = "Il braccio armato è a posto, {name}. Per il resto, chiedi a un sacerdote."
L["Battle Shout, {name}. Not a spell, really. A strongly worded suggestion."] = "Urlo di Battaglia, {name}. Più che un incantesimo, un consiglio energico."
L["RAAAGH! That one was for you, {name}. Everyone else just overheard."] = "RAAAGH! Quello era per te, {name}. Gli altri hanno solo origliato."
L["A little breath from the damned, {name}. They weren't using it."] = "Un po' di fiato dai dannati, {name}. Tanto non lo usavano."
L["Unending Breath, {name}. The fish will have so many questions."] = "Fiato infinito, {name}. I pesci avranno mille domande."
L["Stay down as long as you like, {name}. Something else is holding its breath."] = "Resta giù quanto vuoi, {name}. Il fiato lo trattiene qualcun altro."
L["Swim deep, {name}. If a murloc asks, you're only visiting."] = "Nuota a fondo, {name}. Se un murloc chiede, sei solo di passaggio."
L["Folk will think we're duelling, {name}. Thanks for the {gift}."] = "Penseranno che stiamo duellando, {name}. Grazie per {gift}."
L["{gift} for {buff}. No auctioneer's cut, {name}."] = "{gift} per {buff}. Senza commissioni d'asta, {name}."
L["Beaten to it, {name}! Your {gift} was quicker than my manners."] = "Che tempismo, {name}! {gift} ha battuto le mie buone maniere."
L["{gift} in, {buff} out. Finest economy in all Azeroth."] = "Entra {gift}, esce {buff}. L'economia migliore di tutta Azeroth."
L["{gift}, for me? All I have is this, {name}, but it's heartfelt."] = "{gift}, per me? Ho solo questo, {name}, ma è di cuore."
L["Your {gift} fits perfectly, {name}. Did you measure me?"] = "{gift} mi calza a pennello, {name}. Mi hai preso le misure?"
L["A treaty in spells, {name}: {gift} for {buff}."] = "Un trattato magico, {name}: {gift} per {buff}."
L["{gift}! I feel taller already. Have some {buff}."] = "{gift}! Già mi sento crescere. Ecco {buff} per te."
L["I was about to ask for {gift}, {name}. You read my mind."] = "Stavo per chiederti {gift}, {name}. Mi hai letto nel pensiero."
L["Your {gift} still fizzes, {name}. Here's some fizz back."] = "{gift} frizza ancora, {name}. Eccoti un po' di bollicine."
L["Such a kind {gift}, {name}. I'll tell the whole inn. Twice."] = "{gift}, che gentile, {name}. Lo dirò a tutta la locanda. Due volte."
L["You cast {gift} first, {name}? My mother would despair of me."] = "{gift} prima tu, {name}? Mia madre si vergognerebbe di me."
L["I'll remember your {gift} fondly, {name}. Until it wears off."] = "Ricorderò {gift} con affetto, {name}. Finché non svanisce."
L["{gift} for {buff}, free. Somewhere, a goblin weeps."] = "{gift} per {buff}, gratis. Chissà dove, un goblin piange."
L["Your {gift}, my {buff}. We'll be unbearable now."] = "{gift} da te, {buff} da me. Ora saremo insopportabili."
L["Thanks for the {gift}, {name}. I'll earn it before it fades."] = "Grazie per {gift}, {name}. Ne sarò all'altezza finché dura."
L["For {gift} I'd hand you both moons, {name}. This'll have to do."] = "Per {gift} ti darei entrambe le lune, {name}. Accontentati di questo."
L["You brought {gift}, I brought {buff}. Now it's a party."] = "Tu hai portato {gift}, io {buff}. Ora sì che è una festa."
L["{gift}! I just had three clever thoughts, {name}. This was one."] = "{gift}! Ho appena avuto tre idee geniali, {name}. Questa era una."
L["With {gift}, {name}, I finally understand my own notes. Thanks."] = "Con {gift}, {name}, finalmente capisco i miei appunti. Grazie."
L["Cleverer already, {name}. Clever enough to know I owe you one. Here."] = "Già più intelligente, {name}: so che te ne devo una. Ecco."
L["{gift}, {name}? I'll stand at the front for once. Briefly."] = "{gift}, {name}? Per una volta starò in prima fila. Per poco."
L["Knees, elbows and pride, {name}: all fortified. Thank you."] = "Ginocchia, gomiti e orgoglio, {name}: tutti rinforzati. Grazie."
L["Hit me now, {name}. Actually, don't. But thank you; I'd survive it."] = "Colpiscimi pure, {name}. Anzi, no. Ma grazie: sopravviverei."
L["{gift}! My spirits are lifted, {name}. Literally, it seems."] = "{gift}! Il mio spirito vola, {name}. Letteralmente, pare."
L["I feel twice as calm and half as grumpy, {name}. Thank you."] = "Il doppio della calma e metà del malumore, {name}. Grazie."
L["Shadow-proof, thanks to you, {name}. The whispers are furious."] = "A prova d'ombra grazie a te, {name}. I sussurri sono furiosi."
L["Nothing dark gets in now, {name}. Here's something bright going the other way."] = "Ora il buio non entra, {name}. In cambio, esce un po' di luce."
L["{gift}! A squirrel just nodded at me, {name}. Here's yours."] = "{gift}! Uno scoiattolo mi ha appena salutato, {name}. Ricambio."
L["Tougher hide, sharper senses, {name}. I may have to fight the urge to forage."] = "Pelle più dura, sensi più acuti, {name}. Ora ho voglia di cercare ghiande."
L["I feel all wild and leafy, {name}. Thank you. Sorry if I shed bark."] = "Mi sento un po' bosco, {name}. Grazie. Scusa se perdo corteccia."
L["{gift}, {name}! Nobody's hugging me today. Have this instead."] = "{gift}, {name}! Oggi niente abbracci per me. Tieni questo invece."
L["Prickly now, thanks to you, {name}. More than usual, I mean."] = "Ora sono pungente grazie a te, {name}. Più del solito, intendo."
L["{gift} from you, {name}? I'll try not to found a dynasty."] = "{gift} da te, {name}? Cercherò di non fondare una dinastia."
L["A little better at everything, {name}. Is this how kings feel? No wonder."] = "Un po' meglio in tutto, {name}. È così che si sentono i re? Ecco perché."
L["Stronger arms already, {name}. I'll try not to hug anyone. Thank you."] = "Braccia già più forti, {name}. Eviterò di abbracciare qualcuno. Grazie."
L["With {gift} I could lift a kodo, {name}. I won't, but thank you."] = "Con {gift} potrei sollevare un kodo, {name}. Non lo farò, ma grazie."
L["{gift} from you, {name}, and my first wise act is this."] = "{gift} da te, {name}, e il mio primo gesto saggio è questo."
L["Wiser already, {name}. Wise enough to know a kindness when I see one."] = "Ho già più giudizio, {name}. Abbastanza da riconoscere una gentilezza."
L["{gift}! The monsters forgot me at once, {name}. I won't."] = "{gift}! I mostri mi hanno scordato subito, {name}. Io no."
L["Nothing wants to fight me now, {name}. It's lovely. Thank you."] = "Ora niente vuole combattermi, {name}. Che meraviglia. Grazie."
L["The Light finds me easier now, {name}. It says thank you, and so do I."] = "Ora la Luce mi trova meglio, {name}. Ti ringrazia, e anch'io."
L["Easier to heal now, thanks to you, {name}. My healer thanks you too."] = "Ora curarmi è più facile, {name}. Grazie da me e dal mio guaritore."
L["Blows land softer on me now, {name}. My bruises thank you, and so do I."] = "I colpi ora fanno meno male, {name}. Grazie dai miei lividi, e da me."
L["Every hit gentler, thanks to you, {name}. I'll make sure they notice."] = "Colpi più leggeri grazie a te, {name}. Farò in modo che se ne accorgano."
L["You shouted at me, {name}, and I've never felt so encouraged. Here."] = "Mi hai urlato addosso, {name}, e non ho mai avuto tanto coraggio. Tieni."
L["My ears are ringing, {name}, and my arms feel twice as strong. Thank you!"] = "Mi fischiano le orecchie, {name}, e ho le braccia forti il doppio. Grazie!"
L["I can breathe underwater, {name}! I may never need to, but thank you."] = "Respiro sott'acqua, {name}! Forse non mi servirà mai, ma grazie."
L["Lungs like a murloc, thanks to you, {name}. Mrgl. Sorry. Thank you."] = "Polmoni da murloc, grazie a te, {name}. Mrgl. Scusa. Grazie."
L["We have to stop meeting like this, {name}. Actually, no, we don't."] = "Dobbiamo smetterla di vederci così, {name}. Anzi, no."
L["Again, {name}? Splendid. I've been practising since last time."] = "Ancora tu, {name}? Splendido. Ho fatto pratica dall'ultima volta."
L["You again, {name}? People will start saying we're friends."] = "Di nuovo tu, {name}? La gente inizierà a dire che siamo amici."
L["Same face, same spell, {name}. I do love a tradition."] = "Stessa faccia, stessa magia, {name}. Adoro le tradizioni."
L["Another round, {name}? I'm keeping score, and we're both winning."] = "Un altro giro, {name}? Tengo il punteggio, e stiamo vincendo entrambi."
L["Ah, {name}! My favourite repeat customer."] = "Ah, {name}! La mia clientela più affezionata."
L["Our paths keep crossing, {name}. I think the road is dropping hints."] = "Continuiamo a incrociarci, {name}. Mi sa che la strada ci fa l'occhiolino."
L["Hello again, {name}. Do stop me if you've heard this one."] = "Ciao di nuovo, {name}. Fermami se l'hai già sentita."
L["I kept some aside, {name}, in case you came back. Good instinct, mine."] = "Te ne avevo tenuto un po' da parte, {name}. Che fiuto, il mio."
L["Back already, {name}? I'm starting to think you like me."] = "Già di ritorno, {name}? Comincio a pensare che ti piaccia."
L["{name}, at this point we should just share a reagent pouch."] = "{name}, ormai ci serve una borsa dei reagenti in comune."
L["Same time tomorrow, {name}? I'll bring {buff}. You bring you."] = "Stessa ora domani, {name}? Io porto {buff}. Tu, porta solo te."
L["I've lost count, {name}, and I've decided that's a compliment."] = "Ho perso il conto, {name}, e ho deciso che è un complimento."
L["Keep this up, {name}, and the bards will write a very dull song about us."] = "Continua così, {name}, e i bardi ci dedicheranno una canzone noiosissima."
L["I could do this one in my sleep by now, {name}. I may have."] = "Ormai potrei farlo nel sonno, {name}. Forse l'ho già fatto."
L["{name}, the usual? Of course the usual. It's always the usual."] = "{name}, il solito? Ma certo, il solito. È sempre il solito."
L["We ought to have a secret handshake by now, {name}. Next time, perhaps."] = "Ci manca solo una stretta di mano segreta, {name}. Alla prossima, magari."
L["By now, {name}, I think we've built a small economy between us."] = "Ormai, {name}, tra noi due c'è una piccola economia."
L["Old friends by now, {name}. Well, old acquaintances with excellent timing."] = "Vecchi amici, ormai, {name}. Be', vecchi conoscenti dal tempismo perfetto."
L["Let the record show: {name} and I, undefeated at being prepared."] = "Che resti agli atti: {name} e io, imbattuti nell'essere pronti."
L["Safe walls, warm beds, and now {buff}. You're spoiled, {name}."] = "Mura sicure, letti caldi e ora {buff}. Che lusso, {name}."
L["The guards have it covered, {name}, but I like to be thorough."] = "Ci pensano le guardie, {name}, ma io non lascio nulla al caso."
L["Careful, {name}. Look this capable in town and folk will ask you favours."] = "Occhio, {name}. Se in città sembri così capace, ti chiederanno favori."
L["Not a monster for miles, {name}. Still, one never knows about the cooking."] = "Non c'è un mostro per chilometri, {name}. Ma con la cucina non si sa mai."
L["For the crowds, {name}. In town, they're the real danger."] = "Per la folla, {name}. In città, è lei il vero pericolo."
L["Rest easy, {name}. I'll count that my good deed and go find a pint."] = "Rilassati, {name}. Buona azione fatta: vado a farmi una birra."
L["Even in town, {name}, a dragon has been known to drop in. Better safe."] = "Anche in città, {name}, può piombare un drago. Meglio essere prudenti."
L["Best do it in here, {name}. Out there, nobody stands still long enough."] = "Meglio farlo qui, {name}. Là fuori nessuno sta fermo abbastanza."
L["Out here everything wants to eat you, {name}. Now it'll need a bigger fork."] = "Qui fuori tutto vuole mangiarti, {name}. Ora servirà una forchetta più grande."
L["No guards for miles, {name}, and the boars know it. Take this."] = "Nessuna guardia in giro, {name}, e i cinghiali lo sanno. Prendi."
L["Nobody out here but us and the wildlife, {name}. Let's be the tougher half."] = "Qui ci siamo solo noi e le bestie, {name}. Siamo noi la metà più tosta."
L["If a bear asks, {name}, you were like this when I found you."] = "Se un orso chiede, {name}, eri già così quando ti ho trovato."
L["The wolves have been eyeing you, {name}. This should give them pause."] = "I lupi ti tengono d'occhio, {name}. Questo dovrebbe farli riflettere."
L["Wild country, {name}. Best not to meet it armed with good intentions alone."] = "Terre selvagge, {name}. Meglio non affrontarle con le sole buone intenzioni."
L["Map, canteen, {buff}. Now you can get lost properly, {name}."] = "Mappa, borraccia, {buff}. Ora puoi perderti come si deve, {name}."
L["Camp's a long way off, {name}. Consider this a roof you can carry."] = "L'accampamento è lontano, {name}. Consideralo un tetto portatile."
L["Somewhere in here a villain is rehearsing a speech, {name}. Let's interrupt."] = "Qui dentro un cattivo sta provando il suo discorso, {name}. Interrompiamolo."
L["Whatever waits at the end of this place, {name}, let's make it regret it."] = "Qualunque cosa ci aspetti in fondo, {name}, facciamola pentire."
L["They say nobody leaves here alive, {name}. Let's be rude and prove them wrong."] = "Dicono che da qui nessuno esca vivo, {name}. Facciamo i maleducati: smentiamoli."
L["Our host had years to prepare, {name}. We have {buff}."] = "Il padrone di casa si prepara da anni, {name}. Noi abbiamo {buff}."
L["Nobody builds a dungeon with a back door, {name}. Take this instead."] = "Nessuna segreta ha l'uscita sul retro, {name}. Prendi questo, piuttosto."
L["Dark halls, old traps, worse tempers. At least you're ready, {name}."] = "Sale buie, trappole vecchie, caratteracci. Almeno tu sei a posto, {name}."
L["Better I hand you this now, {name}, than a eulogy later."] = "Meglio darti questo adesso, {name}, che un elogio funebre dopo."
L["There's treasure in here, {name}, and something very large sat on it."] = "Qui c'è un tesoro, {name}, e qualcosa di molto grosso ci sta seduto sopra."
L["Flags, towers, graveyards, {name}. Whatever we're fighting over, take this."] = "Bandiere, torri, cimiteri, {name}. Per qualunque cosa si combatta, prendi."
L["Win or lose, {name}, nobody will say you went in unprepared."] = "Comunque vada, {name}, nessuno dirà che mancavi di preparazione."
L["The graveyard's just over there, {name}. Let's both not visit it."] = "Il cimitero è proprio lì, {name}. Evitiamo di visitarlo, tutti e due."
L["Honour's on the line, {name}. So is the flag. Mostly the flag."] = "In gioco c'è l'onore, {name}. E la bandiera. Soprattutto la bandiera."
L["Stay with the group, {name}. Lone heroes end up in the other side's songs."] = "Resta col gruppo, {name}. Gli eroi solitari finiscono nelle canzoni altrui."
L["Early bird, {name}? Here's something better than a worm."] = "Il mattino ha l'oro in bocca, {name}. E io ho questo per te."
L["Good morning, {name}. Consider this your first cup of something strong."] = "Buongiorno, {name}. Consideralo il tuo primo espresso."
L["Early start, {name}. The day hasn't had a chance to go wrong yet."] = "Di buon'ora, {name}. La giornata non ha ancora fatto in tempo a guastarsi."
L["Not even lunch yet, {name}, and you're already better prepared than I am."] = "Non è nemmeno ora di pranzo, {name}, e la tua preparazione batte già la mia."
L["Morning, {name}. Somewhere, the monsters are still yawning."] = "Buongiorno, {name}. Da qualche parte i mostri sbadigliano ancora."
L["A fresh day and a fresh {buff}, {name}. Let's not waste either."] = "Nuovo giorno e {buff} di giornata, {name}. Non sprechiamoli."
L["Out this late, {name}? The night is hungrier than the day. Take this."] = "In giro così tardi, {name}? La notte ha più fame del giorno. Prendi."
L["Past bedtime, {name}. The sensible folk are asleep, which leaves us."] = "Ora di nanna passata, {name}. La gente saggia dorme: restiamo noi."
L["Can't sleep either, {name}? Then let's be well-protected insomniacs."] = "Nemmeno tu dormi, {name}? Allora facciamo gli insonni ben protetti."
L["Mind the dark, {name}. Not everything out there is as friendly as I am."] = "Occhio al buio, {name}. Là fuori non tutti sono amichevoli come me."
L["It's late, {name}. This should keep you going till the sun remembers us."] = "È tardi, {name}. Questo ti basterà finché il sole non si ricorda di noi."
L["Only the owls and us awake, {name}, and the owls get no {buff}."] = "Svegli solo noi e i gufi, {name}, e ai gufi niente {buff}."
L["Takes one to know one, {name}. Takes one to do it properly, too."] = "Chi si somiglia si piglia, {name}. E si aiuta come si deve."
L["From one of our trade to another, {name}. No need to check my work."] = "Da collega a collega, {name}. Non serve controllare il mio lavoro."
L["Professional courtesy, {name}. We don't charge each other."] = "Cortesia professionale, {name}. Tra colleghi non ci si fa pagare."
L["Two of a kind, {name}. Between us we could write the manual."] = "Della stessa pasta, {name}. Insieme potremmo scrivere il manuale."
L["Don't look so surprised, {name}. Same trainer, I expect."] = "Non stupirti, {name}. Avremo avuto lo stesso istruttore."
L["I'd critique your technique, {name}, but mine looks exactly the same."] = "Criticherei la tua tecnica, {name}, ma la mia è identica."
L["Don't tell the others, {name}, but ours really is the finest calling."] = "Non dirlo agli altri, {name}, ma la nostra è davvero la vocazione migliore."
L["Look at us, {name}. Two experts, making it look easy. It isn't, is it?"] = "Guardaci, {name}. Due esperti che la fanno sembrare facile. Non lo è, vero?"
L["I'd shout some encouragement, {name}, but you do that far better."] = "Ti urlerei un incoraggiamento, {name}, ma tu urli molto meglio di me."
L["Charge in as usual, {name}. I'll simply feel better about it now."] = "Carica come al solito, {name}. Almeno ora mi preoccupo meno."
L["For the one who goes in first, {name}. Somebody has to, and it's never me."] = "Per chi entra per primo, {name}. Qualcuno deve farlo, e non sono mai io."
L["You take the hits so the rest of us don't, {name}. It's the least I can do."] = "Prendi i colpi al posto nostro, {name}. È il minimo che possa fare."
L["Go on, {name}, charge. I'll be right behind you. Quite a long way behind."] = "Vai, {name}, carica. Sarò subito dietro di te. Molto dietro."
L["Save the bubble for later, {name}. This one's from me."] = "Tieni la bolla per dopo, {name}. Questo è da parte mia."
L["You bless everyone else all day, {name}. Here's one going the other way."] = "Tutto il giorno benedici gli altri, {name}. Stavolta tocca a te."
L["The Light already likes you, {name}. Consider this a second opinion."] = "La Luce ti vuole già bene, {name}. Considera questo un secondo parere."
L["Even the Light's own champion needs a hand now and then, {name}."] = "Anche ai campioni della Luce serve una mano, ogni tanto, {name}."
L["I'd ask for a blessing back, {name}, but then we'd be here all day."] = "Ti chiederei una benedizione in cambio, {name}, ma non finiremmo più."
L["One for you, {name}, and a pat on the head for your companion."] = "Questo per te, {name}, e una carezza al tuo compagno."
L["You watch everyone's back from range, {name}. I've got yours."] = "Copri le spalle a tutti dalla distanza, {name}. Io copro le tue."
L["Hunter's Mark for them, {buff} for you, {name}. Much nicer."] = "Marchio del Cacciatore per loro, {buff} per te, {name}. Molto meglio."
L["Aim true, {name}. And if it charges you anyway, run towards the rest of us."] = "Mira bene, {name}. E se ti carica comunque, corri verso di noi."
L["Your pet was looking at me hopefully, {name}. This is for you; tell it sorry."] = "Il tuo famiglio mi guardava speranzoso, {name}. È per te: digli che mi spiace."
L["For the one I never see coming, {name}. Meant as the highest praise."] = "Per chi non vedo mai arrivare, {name}. È il complimento più alto."
L["Quick, {name}, before you vanish again."] = "Presto, {name}, prima che tu sparisca di nuovo."
L["Poison on the blades, {buff} on you. Very thorough, {name}."] = "Veleno sulle lame, {buff} su di te. Che precisione, {name}."
L["I'd slip it in your pocket, {name}, but you'd notice. You always notice."] = "Te lo infilerei in tasca, {name}, ma te ne accorgeresti. Come sempre."
L["For the one who opens every locked box, {name}. This one comes unlocked."] = "Per chi apre ogni scrigno chiuso, {name}. Questo arriva già aperto."
L["For once, {name}, somebody's looking after the priest."] = "Per una volta, {name}, qualcuno cura chi cura."
L["Save your prayers for the rest of us, {name}. This one's already answered."] = "Tieni le preghiere per noi, {name}. Questa è già esaudita."
L["Light or Shadow, {name}, I don't ask which. This suits both."] = "Luce o Ombra, {name}, non chiedo quale. Questo va bene per entrambe."
L["Sit down after this fight, {name}. That's an order, from a grateful patient."] = "Dopo questo scontro, siediti, {name}. Ordine dei tuoi pazienti riconoscenti."
L["You keep us all standing, {name}. Here's a little of it coming back."] = "Ci tieni tutti in piedi, {name}. Eccotene un po' indietro."
L["No voice in your head comes with this one, {name}. Refreshing, isn't it?"] = "Niente voce nella testa, con questo, {name}. Che sollievo, eh?"
L["The Ebon Blade asks no favours, {name}. I'm giving one anyway."] = "La Lama d'Ebano non chiede favori, {name}. Te ne faccio uno comunque."
L["A little warmth, {name}. I know you don't feel the cold. It's the thought."] = "Un po' di calore, {name}. So che non senti il freddo. È il pensiero che conta."
L["You came back from the dead, {name}. The least I can do is help you stay back."] = "Hai lasciato la tomba, {name}. Il minimo è aiutarti a non tornarci."
L["Runes, plague and frost, {name}. Take this too; it completes the set."] = "Rune, pestilenza e gelo, {name}. Aggiungi questo: collezione completa."
L["The elements look after you, {name}, but they don't make house calls."] = "Gli elementi vegliano su di te, {name}, ma non fanno visite a domicilio."
L["Tell the spirits I said hello, {name}. They never write back."] = "Saluta gli spiriti da parte mia, {name}. Non mi rispondono mai."
L["Plant a totem in my honour, {name}. A small one. I'm modest."] = "Pianta un totem in mio onore, {name}. Uno piccolo, per modestia."
L["Earth, fire, water, air and me, {name}. Admittedly the least of the five."] = "Terra, fuoco, acqua, aria e io, {name}. Io valgo meno, lo ammetto."
L["Totems up already, {name}? Then this goes next to them. Don't plant it."] = "Totem già piantati, {name}? Allora questo va accanto a loro. Non piantarlo."
L["A gift for a mage, {name}? Like bringing water to... well, you."] = "Aiutare te, {name}? Come portare acqua al mare. Anzi, a chi la evoca."
L["You solve most problems with sheep, {name}. This covers the rest."] = "Risolvi quasi tutto con le pecore, {name}. Questo copre il resto."
L["You could teleport out of any trouble, {name}. This is for the trouble first."] = "Puoi uscire da ogni guaio con un portale, {name}. Questo è per entrarci."
L["For the clever one, {name}. Please don't thank me by making me a sheep."] = "Per la mente del gruppo, {name}. Non ringraziarmi trasformandomi in pecora."
L["Blink wherever you like, {name}. This comes too."] = "Usa la Traslazione dove vuoi, {name}. Questo ti segue."
L["Entirely demon-free, {name}. I checked."] = "Senza demoni, {name}. Ho controllato."
L["Your imp may be jealous, {name}. Tell it there's plenty to go round."] = "Il tuo imp potrebbe essere geloso, {name}. Digli che ce n'è per tutti."
L["No contract, no fine print, {name}. Just a gift."] = "Niente contratto né clausole, {name}. Solo un regalo."
L["For the one who hands out healthstones, {name}. Nobody ever thanks you."] = "Per chi distribuisce Pietre della Salute, {name}. Nessuno ti ringrazia mai."
L["Here, {name}. Summon the rest of us later and we'll call it even."] = "Tieni, {name}. Poi evochi il resto di noi e siamo pari."
L["Roll wherever you like, {name}. This rolls with you."] = "Rotola dove vuoi, {name}. Questo rotola con te."
L["Brew first or fight first, {name}? Either way, take this."] = "Prima la birra o prima la rissa, {name}? In ogni caso, prendi."
L["Inner peace for you, {name}, and outer peace too, as long as this lasts."] = "Pace interiore per te, {name}, e anche esteriore, finché dura."
L["Chi flows better with a little help, {name}. Or so a monk once told me."] = "Il chi scorre meglio con un aiutino, {name}. Così mi disse un monaco."
L["Kick, flip, roll, {name}. I'll just stand here and do this bit."] = "Calci, capriole, rotolate, {name}. Io sto qui e faccio questa parte."
L["Tell the bear this is for them too, {name}."] = "Di' all'orso che è anche per lui, {name}."
L["Hold still, {name}. I've never once managed to catch you as a cheetah."] = "Non muoverti, {name}. In forma di ghepardo non ti ho mai preso."
L["Nature looks after you already, {name}. Today she sent me to help."] = "La natura ti protegge già, {name}. Oggi ha mandato me a darle una mano."
L["Whatever shape you're in next, {name}, this goes with you."] = "Qualunque forma prenderai, {name}, questo viene con te."
L["For the forest's friend, {name}. Give my regards to the trees."] = "Per chi parla con la foresta, {name}. Salutami gli alberi."
L["You were not prepared, {name}. Now you are."] = "Non siete preparati, diceva Illidan. Tu ora sì, {name}."
L["Ten thousand years in a cell, {name}. You've earned a small kindness."] = "Diecimila anni in cella, {name}. Una piccola gentilezza te la meriti."
L["You gave up so much to fight the Legion, {name}. Here's a little back."] = "Hai dato tanto per combattere la Legione, {name}. Eccoti un po' in cambio."
L["For the one who leaps first, {name}. Do land somewhere friendly."] = "Per chi salta prima di tutti, {name}. Atterra in un posto amichevole."
L["Fel and fury, {name}, and now a little kindness. It'll balance out."] = "Fuoco vile e furia, {name}, e ora un po' di gentilezza. Si compenserà."
L["For you, {name}. Please don't breathe on it."] = "Per te, {name}. Ti prego, non soffiarci sopra."
L["A little help for a dragon, {name}. I'll be telling my grandchildren."] = "Un aiutino a un drago, {name}. Lo racconterò ai miei nipoti."
L["The Aspects sent you out into the world, {name}. I'm making it friendlier."] = "Gli Aspetti ti hanno mandato nel mondo, {name}. Io lo rendo più accogliente."
L["Take to the skies after this, {name}. I'll wave from down here."] = "Dopo questo, spicca il volo, {name}. Io ti saluto da quaggiù."
L["A dragon on our side, {name}. I've never felt safer being generous."] = "Un drago alleato, {name}. Essere generosi non è mai stato così sicuro."
L["{buff} for a mage, {name}. Like lending a library a book."] = "{buff} tra maghi, {name}. Come prestare un libro a una biblioteca."
L["Mage to mage, {name}: I won't ask you for water if you won't ask me."] = "Da mago a mago, {name}: io non ti chiedo l'acqua se tu non la chiedi a me."
L["Two mages, {name}. Between us we can portal anywhere and still be late."] = "Due maghi, {name}. Portali ovunque, e arriviamo comunque in ritardo."
L["A mage for a mage, {name}. The Kirin Tor would call this peer review."] = "Magia tra maghi, {name}. Il Kirin Tor la chiamerebbe revisione tra pari."
L["Priest to priest, {name}: who blesses the blessers? Today, me."] = "Da sacerdote a sacerdote, {name}: chi benedice i benedicenti? Oggi io."
L["Between us priests, {name}, we'll both pretend the tank listens."] = "Tra noi sacerdoti, {name}: facciamo finta che il tank ascolti."
L["A priest looking after a priest, {name}. It feels almost forbidden."] = "Sacerdoti che si curano a vicenda, {name}. Sa quasi di peccato."
L["Two priests, {name}. Twice the praying and half the panic."] = "Due sacerdoti, {name}. Il doppio delle preghiere e metà del panico."
L["Two druids, {name}. The Cenarion Circle would call this a quorum."] = "Due druidi, {name}. Per il Circolo Cenariano c'è il numero legale."
L["Druid to druid, {name}: bear or cat, I'd know you by the leaves in your hair."] = "Da druido a druido, {name}: orso o gatto, ti riconosco dalle foglie nei capelli."
L["From one shapeshifter to another, {name}: this one fits every shape."] = "Da mutaforma a mutaforma, {name}: questo va bene in ogni forma."
L["No handshake, {name}. Two druids, and neither of us has the right shape for it."] = "Niente stretta di mano, {name}. Due druidi, e nessuno dei due ha la forma giusta."
L["Paladin to paladin, {name}: I won't mention the bubble if you don't."] = "Da paladino a paladino, {name}: io non nomino la bolla se non lo fai tu."
L["A blessing for a paladin, {name}. Now we're both insufferably radiant."] = "Benedizione tra paladini, {name}. Ora siamo insopportabilmente radiosi."
L["Two paladins, {name}. Somewhere, a priest is quietly relieved."] = "Due paladini, {name}. Da qualche parte, un sacerdote respira sollevato."
L["One of us should be humble about this, {name}. Neither of us will be."] = "Uno di noi dovrebbe essere umile, {name}. Nessuno dei due lo sarà."
L["Warlock to warlock, {name}: keep your imp away from mine. They gossip."] = "Tra stregoni, {name}: tieni il tuo imp lontano dal mio. Spettegolano."
L["Fellow warlock, {name}? Then you know this one's actually harmless. Honestly."] = "Collega stregone, {name}? Allora sai che questo è davvero innocuo. Parola mia."
L["Two warlocks, {name}. Let's not compare soul shards in public."] = "Due stregoni, {name}. Non confrontiamo i frammenti d'anima in pubblico."
L["Between us, {name}, the demons do all the work. This bit I do myself."] = "Tra noi, {name}, tutto il lavoro lo fanno i demoni. Questo lo faccio io."
L["Two warriors, {name}. Somewhere, a healer just sighed."] = "Due guerrieri, {name}. Chissà dove, un guaritore sospira."
L["Warrior to warrior, {name}: first into the fight buys the drinks. I'm buying."] = "Da guerriero a guerriero, {name}: chi entra per primo paga da bere. Offro io."
L["Shout for shout, {name}. We'll deafen the whole place together."] = "Urlo per urlo, {name}. Insieme assorderemo tutto il posto."
L["No plan, {name}? Perfect. We'll get along."] = "Nessun piano, {name}? Perfetto. Andremo d'accordo."
L["Aye, {name}, ye only had to ask. Hold still now!"] = "Ma certo, {name}, bastava chiedere! E ora non muoverti."
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "Tieni, {name}, un aiutino per tenerti in piedi."
L["My thanks, {name}. Allow me to return the kindness."] = "Ti ringrazio, {name}. Permettimi di ricambiare la cortesia."
L["Of course, {name}. Stand fast a moment."] = "Certo, {name}. Non muoverti per un istante."
L["The road ahead is long, {name}. Take this with you."] = "La strada è lunga, {name}. Porta questo con te."
L["Ishnu-alah, {name}. Your kindness is returned."] = "Ishnu-alah, {name}. Ricambio la tua gentilezza."
L["Elune-adore, {name}. Walk softly beneath the stars."] = "Elune-adore, {name}. Cammina lieve sotto le stelle."
L["The Light rewards kindness, {name}, and so shall I."] = "La Luce premia la gentilezza, {name}, e così farò anch'io."
L["Of course, {name}. May the Naaru guide your steps."] = "Certo, {name}. Che i Naaru guidino i tuoi passi."
L["The Light is with you, {name}. Go in peace."] = "La Luce è con te, {name}. Va' in pace."
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "Grazie infinite, {name}. Gilneas non dimentica mai una gentilezza."
L["Lok'tar ogar, {name}! Take this into battle."] = "Lok'tar ogar, {name}! Portalo con te in battaglia."
L["The Earth Mother sees your kindness, {name}. I return it."] = "La Madre Terra vede la tua gentilezza, {name}. Io la ricambio."
L["Of course, {name}. Stand tall and be at peace."] = "Certo, {name}. Tieni alta la testa e resta in pace."
L["Walk with the Earth Mother, {name}."] = "Cammina con la Madre Terra, {name}."
L["Sure ting, {name}. Hold still now."] = "Sicuro, {name}. Mo' nun te movere."
L["Da loa be watchin' over ya, {name}."] = "'E loa te guardano 'e spalle, {name}."
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "Tanta cortesia ti fa onore, {name}. Anar'alah belore."
L["Anar'alah belore, {name}. May the sun guide you."] = "Anar'alah belore, {name}. Che il sole ti guidi."
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "Prendo nota della tua generosità, {name}. Suramar ricorda i suoi amici."
L["Thank you, {name}! The caravan always repays a kindness."] = "Grazie, {name}! La carovana ricambia sempre una gentilezza."
L["Every traveller needs something for the road, {name}."] = "Ogni viandante merita qualcosa per il viaggio, {name}."
L["Of course, {name}. Patience, and it is done."] = "Certo, {name}. Un po' di pazienza, ed è fatto."
L["Take this, {name}. Even a dragon needs allies."] = "Prendi, {name}. Anche un drago ha bisogno di alleati."
L["Thank you, {name}. The Alliance looks after its own."] = "Grazie, {name}. L'Alleanza si prende cura dei suoi."
L["Of course, {name}. Allies help each other."] = "Certo, {name}. Gli alleati si aiutano a vicenda."
L["For the Alliance, {name}! Stay strong out there."] = "Per l'Alleanza, {name}! Tieni duro là fuori."
L["Strength and honour, {name}. Your kindness is repaid."] = "Forza e onore, {name}. La tua gentilezza è ripagata."
L["Consider it done, {name}. For the Horde."] = "Consideralo fatto, {name}. Per l'Orda."
L["For the Horde, {name}! Go with strength."] = "Per l'Orda, {name}! Va' e sii forte."
L["Thank you, {name}. Good hearts are found everywhere."] = "Grazie, {name}. I cuori buoni si trovano ovunque."
L["Gladly, {name}, whatever banner you fly."] = "Con piacere, {name}, qualunque sia il tuo stendardo."
L["Friends can come from any side, {name}."] = "Gli amici possono venire da ogni parte, {name}."
L["Safe travels, {name}. Take some {buff} with you."] = "Buon viaggio, {name}. Porta con te un po' di {buff}."
L["Returning a favour:"] = "Ricambiando un favore:"
L["Answering a request:"] = "Rispondendo a una richiesta:"
L["In your group:"] = "Nel tuo gruppo:"
L["Offering unasked:"] = "Di tua iniziativa:"
L["Returning a favour of %s:"] = "Ricambiando un favore di %s:"
L["Meeting somebody a third time:"] = "Incontrando qualcuno per la terza volta:"
L["(nothing -- speech off, or no usable lines)"] = "(niente -- messaggi disattivati o nessuna frase utilizzabile)"
L["In character"] = "Nel personaggio"
L["an in-character line"] = "una frase adatta al tuo personaggio"
L["Favour ledger"] = "Registro dei favori"
L["Close (Escape works too)"] = "Chiudi (funziona anche Esc)"
L["No favours recorded today."] = "Nessun favore registrato oggi."
L["Nothing you cast could return today's favours."] = "Nulla di ciò che lanci poteva ricambiare i favori di oggi."
L["Returned %d of 1 favour today."] = "Favori ricambiati oggi: %d su 1."
L["Returned %d of %d favours today."] = "Favori ricambiati oggi: %d su %d."
L["1 favour still owed."] = "1 favore ancora da ricambiare."
L["%d favours still owed."] = "%d favori ancora da ricambiare."
L["You gave 1 buff unprompted today."] = "Oggi hai dato 1 beneficio di tua iniziativa."
