L["Automatic (%s, until you have put one up)"] = "Automatico (%s, finché non ne lanci uno)"
L["Automatic reminds you only while your group role is tank; Always reminds you whenever it is not up."] = "Automatico te lo ricorda solo quando il tuo ruolo nel gruppo è difensore; Sempre te lo ricorda ogni volta che non ce l'hai."
L["Reminds you when none of these is up. Automatic takes the one you had up last."] = "Te lo ricorda quando non ne hai nessuno attivo. Automatico sceglie quello che avevi attivo l'ultima volta."
L["Until you have had one up: %s in a dungeon or raid, %s elsewhere."] = "Finché non ne lanci uno: %s in spedizioni e incursioni, %s altrove."
L["Don't remind me"] = "Non ricordarmelo"
