L["These settings are shared by your other characters (profile: %s)."] = "Queste impostazioni sono condivise con i tuoi altri personaggi (profilo: %s)."
L["The Profiles tab also copies settings as text to share."] = "Nella scheda Profili puoi anche copiarle come testo da condividere."
L["Give this character its own settings"] = "Dai a questo personaggio impostazioni proprie"
L["Copies these settings into a profile named after this character; changes made after that stay on this character."] = "Copia queste impostazioni in un profilo con il nome di questo personaggio; le modifiche successive restano solo su questo personaggio."
L["1. Who to buff"] = "1. A chi dare un beneficio"
L["Offer my buff to"] = "Proponi il mio beneficio a"
