L["Below %d%% only favours, requests and your own buff are offered; the rest come back at %d%%."] = "Sotto il %d%% vengono proposti solo favori, richieste e il tuo beneficio personale; gli altri tornano al %d%%."
L["Below %d%% only favours and requests are offered; the rest come back at %d%%."] = "Sotto il %d%% vengono proposti solo favori e richieste; gli altri tornano al %d%%."
